quests[31481] = { id = 31481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Furcht selbst", description = "Während meiner Zeit hier habe ich die eine oder andere Pandarenweisheit aufgeschnappt. Ganz besonders gefällt mir diese hier:\n\n\"Die Furchtsamen bekommen Angst, bevor es Probleme gibt, die Feiglinge verspüren sie, wenn es Probleme gibt. Die Tapfersten unter uns spüren die Angst erst, nachdem die Probleme beseitigt wurden.\"\n\nIst das wirklich so? Wir werden es bald erfahren.\n\nDas Sha der Angst ist zur Terrasse des Endlosen Frühlings geflohen. Verfolgt es, besiegt es, und reißt ihm den Geist aus, sofern es einen hat.\n\nEuer Mut soll stattlich belohnt werden.", sourceObjective = "Besiegt das Sha der Angst auf der Terrasse des Endlosen Frühlings und holt Euch die Schimäre der Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[31482] = { id = 31482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atem des Schwarzen Prinzen", description = "<Furorions durchdringende rote Augen haben Euch fest im Blick.>\n\nSolche wie Euch findet man nur selten, {name}.\n\nIhr seid genau, wonach ich suchte: Eine Person mit dem Potenzial, Ereignisse auf weltweiter Ebene zu beeinflussen.\n\nKommt nun, ich versprach Euch eine Belohnung, und die sollt Ihr auch haben! Östlich von dieser Höhle liegt eine Reihe steinerner Treppen, die zu einem Aussichtspunkt führen, den die Einheimischen \"Des Steinmetz' Torheit\" getauft haben. Trefft Euch dort mit mir.", sourceObjective = "Geht bis ans obere Ende der Steintreppe bei des Steinmetz' Torheit und holt Euch bei Furorion Eure Belohnung ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31483] = { id = 31483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheil im Verzug", description = "Der Feldzug der Pandaren hat gerade erst begonnen! Wir wenden unsere Aufmerksamkeit nun dem fortwährenden Konflikt zwischen der Allianz und der Horde zu.\n\nMeine Kontaktpersonen in Rabenholdt berichten mir, dass die 7. Legion der Allianz und eine beachtliche Invasionsstreitmacht der Horde sich der Südküste Pandarias nähern. Ob es uns nun gefällt oder nicht: Pandaria könnte schon bald zu einem Schlachtfeld werden.\n\nFürs Erste sind wir hier fertig, aber ich möchte, dass Ihr Euch bei mir meldet, wenn die Flotte eintrifft. Dann... werden wir gemeinsam in Aktion treten!", sourceObjective = "Setzt Euch mit Furorion in Verbindung, wenn Eure Kriegsflotte die Südküste von Pandaria erreicht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[31484] = { id = 31484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hisek Tracking Quest" }
quests[31486] = { id = 31486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was ich übers Kochen weiß", description = "Ich bin so froh, dass Euch mein Essen schmeckt. Wärt Ihr vielleicht an den Rezepten interessiert? Falls ja, solltet Ihr sie aus erster Hand von meinen Lehrern vom Halbhügelmarkt lernen. Alles, was ich über die Küche weiß, habe ich bei ihnen gelernt.\n\nUnd wenn Ihr sowieso in diese Gegend kommt, könntet Ihr dann vielleicht Sungshin Eisentatz diese Nachricht überbringen? Sie war meine Lieblingslehrerin. Ich vermisse sie, und ich möchte, dass sie das auch weiß.", sourceObjective = "Überbringt Sungshin Eisentatz den Brief. Sie unterrichtet auf dem Halbhügelmarkt.", progress = "Ihr habt einen Brief für mich?", completion = "Oh, wie aufmerksam. Ich höre immer sehr gerne von meinen ehemaligen Schülern.", sourceObjectiveStatus = "unverified-source-field" }
quests[31487] = { id = 31487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misstöne", description = "Mit Schallgeflüster die Kunchong zu manipulieren war nur die allererste Phase meiner Forschungen und doch scheint es, als ob das Reich diese Technik vollständig übernommen hat. Die Manipulatoren der Shek'zeer sind zu ungeduldig, eine gebührliche Verbindung mit ihren Kunchong einzugehen.\n\nIhre Faulheit wird sie teuer zu stehen kommen.\n\nSchlagt die Stimmgabel nahe der Schreckenskunchong in den Gelegen an und seht, wie sie vor Verwirrung taumeln und ihre Herren angreifen werden. Nutzt diesen Vorteil aus und macht ihnen den Garaus.", sourceObjective = "Tötet 4 Schreckenskunchong und 6 Shek'zeer Manipulatoren in den Gelegen von Shek'zeer. Die Stimmgabel der Verwirrung wird die Kunchong verwirren und schwächen.", completion = "Möge Euch dies eine Mahnung sein. Die Kunchong sollte man sowohl fürchten als auch respektieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[31488] = { id = 31488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremd in einem fremden Land", description = "Verzeihung, {class}. Heißt Ihr {name}?\n\nEine Gestalt in einem dunklen Umhang hat mich gebeten, Euch das hier zu geben. Es war eine Reisende von hinter den Nebeln so wie Ihr, aber - nun, ich habe ihr nicht getraut.\n\nDie Nachricht kommt von einer Taverne an der Verhüllten Treppe. Ich gebe Euch die Nachricht, aber... Ihr solltet auf Euch achtgeben, wenn Ihr Euch dort hinaufwagt!", sourceObjective = "Sucht den \"Schwarzen Prinzen\" in der Taverne im Nebel an der Verhüllten Treppe auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31489] = { id = 31489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremd in einem fremden Land", description = "Verzeihung, {class}. Heißt Ihr {name}?\n\nEine Gestalt in einem dunklen Umhang hat mich gebeten, Euch das hier zu geben. Es war eine Reisende von hinter den Nebeln so wie Ihr, aber - nun, ich habe ihr nicht getraut.\n\nSie erwähnte den Namen \"Furorion\". Könnt Ihr damit etwas anfangen?\n\nIch gebe Euch die Nachricht, aber... Ihr solltet auf Euch achtgeben, wenn Ihr mit diesen Leuten zu tun habt.", sourceObjective = "Sucht Furorion in der Taverne im Nebel an der Verhüllten Treppe auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31490] = { id = 31490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen das Fußvolk", description = "Das Wichtigste zuerst: Wir müssen dringend einige Kreuzfahrer loswerden.\n\nUnd wenn ich davon spreche, den Scharlachroten Kreuzzug loszuwerden, meine ich, ihn auszulöschen: ALLE Kreuzfahrer bis hinunter in die untersten Dienstränge!", sourceObjective = "Tötet 50 Mitglieder des Scharlachroten Kreuzzugs in den Scharlachroten Hallen.", completion = "Ein guter Anfang, {name}!\n\nJetzt dauert es nicht mehr lange, bis der Scharlachrote Kreuzzug nur noch eine hässliche Fußnote der Geschichte sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[31491] = { id = 31491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Abstand", description = "Xuen hat einst den letzten Kaiser von Pandaria vor die folgende Herausforderung gestellt: Stellt Euch in die Mitte des Raums und wehrt Wellen von Mönchen mit nichts weiter als einem drei Meter langen Stab ab.\n\nMein Rekord steht bei zehn. Gelingt es Euch, das zu schlagen?", sourceObjective = "Haltet mindestens 10 Tigertempelmönche mit dem Dreimeterstab zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[31492] = { id = 31492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fackel der Stärke", description = "Xuen hat sich eine Aufgabe ausgedacht, die dazu dienen soll, die \"Stärke zu verfeinern\". Ich glaube allmählich, dass der Begriff \"Stärke\" für ihn eine andere Bedeutung hat als für den Rest von uns.\n\nHier, bringt diese Fackel auf die Tore des Tempels. Wenn Ihr das schafft, ohne dass die Fackel erlischt, habt Ihr die Aufgabe bestanden.\n\nSetzt Euch aber auf keinen Fall mit der Fackel auf ein Reittier. Dann geht sie aus. Das könnt Ihr mir ruhig glauben.", sourceObjective = "Tragt die Fackel der Stärke zu den Toren des Tempels des Weißen Tigers, ohne dass sie erlischt.", completion = "Alle Achtung! Ihr habt's geschafft! Ich scheitere meist an einer dieser Windböen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31493] = { id = 31493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen von Sicherheit und Ordnung", description = "Hier in den Hallen gibt es ein Buch, das großen Wert für mich hat.\n\nAber leider befindet es sich im Besitz von Flammenwirker Koegler. Ich habe schon mehrmals versucht, in seine Nähe zu kommen, aber es hat nie funktioniert.\n\nVielleicht habt Ihr ja mehr Glück. Aber passt auf Euch auf: Ich habe gehört, dass er komplett wahnsinnig geworden sein soll. Der Flammenwirker plant, alle Bücher der Bibliothek zu verbrennen.\n\nWahrscheinlich wird er dabei gleich die Scharlachroten Hallen selbst niederbrennen.", sourceObjective = "Holt Euch den Kodex des Kreuzzugs.", progress = "Ich muss unbedingt diesen Kodex in meinen Besitz bringen.", completion = "Ah, da ist er ja!\n\n<Die vermummte Kreuzfahrerin reibt sich beim Anblick des Kodex voller Vorfreude die Hände.>\n\nUnd jetzt habe ich eine Namensliste aller Mitglieder des Scharlachroten Kreuzzugs!\n\nNur für den Fall, dass jemand nicht ordnungsgemäß gelistet ist. Ich halte in solchen Dingen gerne Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31494] = { id = 31494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihren Fängen entronnen", description = "Die Manipulatoren der Shek'zeer sperren junge Kunchong in das Gelege und setzen sie reinen Furchtenergien aus, die sie korrumpieren und ihr Wachstum beschleunigen.\n\nAbscheulich! Das lasse ich nicht zu!\n\nBrecht die Käfige auf und entlasst die Jungtiere in die Freiheit.", sourceObjective = "Brecht Kunchongkäfige auf, um 8 Kunchongjungtiere in den Gelegen von Shek'zeer freizulassen.", completion = "Ja, ich konnte sehen, wie sie sich erhoben. Ein wunderschöner Anblick!", sourceObjectiveStatus = "unverified-source-field" }
quests[31495] = { id = 31495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen das Fußvolk", description = "Das Wichtigste zuerst: Wir müssen dringend einige Kreuzfahrer loswerden.\n\nUnd wenn ich davon spreche, den Scharlachroten Kreuzzug loszuwerden, meine ich, ihn auszulöschen: ALLE Kreuzfahrer bis hinunter in die untersten Dienstränge!", sourceObjective = "Tötet 50 Mitglieder des Scharlachroten Kreuzzugs in den Scharlachroten Hallen.", progress = "Passt auf: Ich kümmere mich um die Feinde abseits der Front, die hinter den verschlossenen Türen.\n\nAber ich darf meine Tarnung nicht aufdecken. Aus diesem Grund wäre es großartig, wenn Ihr Euch um die auf dem Schlachtfeld kümmern könntet.", completion = "Ein guter Anfang, {name}!\n\nJetzt dauert es nicht mehr lange, bis der Scharlachrote Kreuzzug nur noch eine hässliche Fußnote der Geschichte sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[31496] = { id = 31496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kostprobe vom Feinsten", description = "Die Wunder des Kyparisaftes versetzen mich immer wieder in Erstaunen. Neben seinen zahlreichen Eigenschaften und Anwendungen lässt sich der Saft zu einem nahrhaften und äußerst aromatischen Elixier verfeinern.\n\nIhr werdet nirgendwo im Reich eine exquisitere Zubereitung dieses Gebräus finden als im Palast selbst. Gewiss finden sich doch in den Heimen der Getreuen Zapfstellen, die bis zum Rand mit diesem süßen Nektar gefüllt sind.\n\nFüllt mir diesen Krug an den Zapfstellen und bringt ihn mir. Ich sehne mich danach, das kaiserliche Ambrosia noch einmal zu schmecken.", sourceObjective = "Benutzt das Harzgefäß an den kaiserlichen Zapfstellen vor dem Herzen der Angst viermal, um es zu füllen.", completion = "Ah, ja, gebt her! Schnell! Meine Vorderbeine zittern vor Erwartung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31497] = { id = 31497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen von Sicherheit und Ordnung", description = "Hier in den Hallen gibt es ein Buch, das großen Wert für mich hat.\n\nAber leider befindet es sich im Besitz von Flammenwirker Koegler. Ich habe schon mehrmals versucht, in seine Nähe zu kommen, aber es hat nie funktioniert.\n\nVielleicht habt Ihr ja mehr Glück. Aber passt auf Euch auf: Ich habe gehört, dass er komplett wahnsinnig geworden sein soll. Der Flammenwirker plant, alle Bücher der Bibliothek zu verbrennen.\n\nWahrscheinlich wird er dabei gleich die Scharlachroten Hallen selbst niederbrennen.", sourceObjective = "Holt Euch den Kodex des Kreuzzugs.", progress = "Ich muss unbedingt diesen Kodex in meinen Besitz bringen.", completion = "Ah, da ist er ja!\n\n<Die vermummte Kreuzfahrerin reibt sich beim Anblick des Kodex voller Vorfreude die Hände.>\n\nUnd jetzt habe ich eine Namensliste aller Mitglieder des Scharlachroten Kreuzzugs!\n\nNur für den Fall, dass jemand nicht ordnungsgemäß gelistet ist. Ich halte in solchen Dingen gerne Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[31498] = { id = 31498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungsmodus der Jadeschlange - Trostpreis (Nter)" }
quests[31499] = { id = 31499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungsmodus der Jadeschlange - Bronze (Nter)" }
quests[31500] = { id = 31500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungsmodus der Jadeschlange - Silber (Nter)" }
quests[31501] = { id = 31501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungsmodus der Jadeschlange - Gold (Nter)" }
quests[31502] = { id = 31502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestutzte Flügel", description = "Die jungen Flieger dieser Ära sind faszinierend. Über ihre außergewöhnliche Wendigkeit und Ausdauer verfügten zu meiner Zeit nur unglaublich geschickte oder erfahrene Flieger.\n\nDas würde auf eine Art der Evolution in der Flügelstruktur hindeuten... Oder vielleicht eine Weiterentwicklung in der Ausbildung? Herbeigeführte genetische Mutation? Selektive Züchtung?\n\nAch! Ohne Gewebeproben lässt sich das unmöglich mit Gewissheit sagen.\n\nBringt mir ihre Flügel! Und versucht sie dabei nicht zu ruinieren, ja? Ich brauche sie intakt!", sourceObjective = "Sammelt 24 Nadlerflügel von Nadlern der Shek'zeer in den Gelegen von Shek'zeer.", progress = "Habt Ihr die Proben?", completion = "Hervorragend, sie sind in erstklassigem Zustand.", sourceObjectiveStatus = "unverified-source-field" }
quests[31503] = { id = 31503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abkürzung zum Ruin", description = "Unter den Getreuen gibt es einen Champion, Vesswache Na'kal, dessen Stärke nicht aus seiner Erfahrung oder Entwicklung herrührt, sondern aus genetischer Modifikation. Er sollte als Musterbeispiel für die Zukunft der Mantis dienen - für die kranke Vorstellung, dass wir stark geboren werden könnten, ohne selbst etwas dazu zu tun.\n\nEr ist eine Pervertierung meiner Arbeit! Die Genverbesserung war AUSSCHLIESSLICH für reife Veteranen gedacht, die den Schwarm bereits hinter sich gelassen haben!\n\nVernichtet ihn. Vielleicht lernt Großkaiserin Shek'zeer daraus, dass Abkürzungen zum Ruin führen.", sourceObjective = "Tötet Vesswache Na'kal vor dem Herzen der Angst.", completion = "Meine Verbesserungen sind Werkzeuge für erfahrene Krieger und keine Spielzeuge für diese törichten Kinder!", sourceObjectiveStatus = "unverified-source-field" }
quests[31504] = { id = 31504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrüstung", description = "Wenn die Agenten der Großkaiserin noch nach den Sicherheitsstandards meiner Zeit arbeiten, werden sie überall in den Gelegen gewaltige Pheromonminen versteckt haben.\n\nDiese könnte sie durch ein bloßes Flüstern alle gleichzeitig hochgehen lassen, um den Palast einzuhüllen und ganzen Belagerungsarmeen die Kräfte zu rauben.\n\nWenn wir bei einer größeren Konfrontation auf Erfolg hoffen wollen, müssen wir die Minen entschärfen. Mein... \"Geschenk\" an Euch, als wir uns begegneten, wird Euch in die Lage versetzen, die Minen zu sehen. Löst sie aus und begebt Euch in eine sichere Entfernung.", sourceObjective = "Schaltet 8 Pheromonminen rund um die Gelege von Shek'zeer und das Herz der Angst aus.", completion = "Ihr wart den Pheromonen doch nicht ausgesetzt? Das könnte nämlich zu... ach, was soll ich Euch mit Details beunruhigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31505] = { id = 31505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vesswachenpflichten", description = "Vesswache Vik'az koordiniert die Verteidigungstruppen in Zan'vess. Er ist im Kampf so viel wert wie zehn Mantis, und seine Gegenwart inspiriert die Zan'thik, die an seiner Seite kämpfen.\n\nIch brauche wohl kaum zu erwähnen, dass wir ihn tot sehen wollen.\n\nEr patrouilliert in dem Siedlungsbereich im Zentrum der Insel.", sourceObjective = "Tötet Vesswache Vik'az in Zan'vess.", completion = "Ihre Champions fallen einer nach dem anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31506] = { id = 31506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fesseln der Manipulation", description = "Die Zan'thik verfügen über eine ganze Armee von... Arbeitsverpflichteten.\n\nYaungol tragen spezielle Fesseln, die die Auswirkungen von Schallmanipulationen verstärken und verlängern. Nur dank dieser Technik können die Manipulatoren der Zan'thik solch eine große Zahl an Knechten kontrollieren, die unaufhörlich in den Steinbrüchen für sie schuften müssen.\n\nDiese Fesseln würde ich gern untersuchen.", sourceObjective = "Sammelt 6 Fesseln der Zan'thik von gedankengefesselten Minenarbeitern und gedankengefesselten Schlägern in Zan'vess.", progress = "Das werdet Ihr doch schaffen, nicht wahr?", completion = "Wirklich ausgeklügelte Vorrichtungen. Ich habe das Gefühl, die werden sich noch als nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31507] = { id = 31507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernschmelze", description = "Die Giftstecherskorpione auf Zan'vess werden schon von klein auf mit Saft ernährt, der eine faszinierende Mutation bewirkt, bei der ihr natürlicher Panzer von Bern durchdrungen wird. Das ist nichts anderes als organisches Kyparit - die gleiche Substanz, die zum Schmieden der meisten Waffen und Rüstungen des Reiches verwendet wird.\n\nIch glaube, ich habe eine Methode gefunden, Kyparit chemisch aufzuschließen, aber sie muss noch getestet werden. Setzt diese Granaten gegen die Giftstecher der Zan'thik ein und beobachtet die Ergebnisse.", sourceObjective = "Tötet 6 Giftstecher der Zan'thik in Zan'vess. Setzt Korvens experimentelle Granate ein, um ihren Panzer zu durchdringen.", completion = "Das Kyparit hat sich also entzündet? Faszinierend!\n\nNicht ganz das, worauf ich gehofft hatte, aber immerhin.", sourceObjectiveStatus = "unverified-source-field" }
quests[31508] = { id = 31508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probenanforderung", description = "Kyparitwürmer können sich extrem gut anpassen, um ihre Umwelt zu imitieren. Sie können außerdem auf eine gewaltige Größe anwachsen, und das in einem Tempo, das für die meisten Kreaturen unerhört ist.\n\nIhre Physiologie könnte wertvolle Einblicke in weitere Mutationen bieten.\n\nBringt mir Splitterproben von Kyparitkriechern in den Untiefen bei Zan'vess.", sourceObjective = "Sammelt 6 Kyparitsplitter von Kyparitkriechern im Salzigen Schlick.", progress = "Habt Ihr die Proben?", completion = "Na seht an, Ihr habt es tatsächlich geschafft. Ich war schon fast darauf gefasst, Eure Reste mit einem Krug aus dem Schlamm schöpfen zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31509] = { id = 31509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwurzelte Furcht", description = "Die Folgen von Shek'zeers Wahnsinn werden noch lange nach dem Ende ihrer Herrschaft zu spüren sein. Wir werden noch viele Jahre damit zu kämpfen haben, unser Land zu heilen, und am Ende werden sich unsere Bemühungen womöglich doch als nutzlos erweisen.\n\nEine neue Spezies von Sha-verderbter Flora hat begonnen, in der Nähe von Zan'vess Wurzeln zu schlagen. Vernichtet alle Pflanzen, die Ihr findet, aber nehmt Euch in Acht – man kann nie wissen, welch unheilvolle Verteidigungsmechanismen sie haben mögen.", sourceObjective = "Vernichtet 15 Furchtsporenknollen in Zan'vess und im Salzigen Schlick.", completion = "Eine interessante Spezies, aber die Risiken, sie zu Studienzwecken zu behalten, sind zu groß.", sourceObjectiveStatus = "unverified-source-field" }
quests[31510] = { id = 31510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt ist Ruhe", description = "In der südwestlichen Ecke von Zan'vess liegen die Flüsternden Steine. Ähnlich wie die Türme hier sind sie für die Übertragung von Schallsignalen über weite Entfernungen sehr wichtig.\n\nEin Gehilfe der Kaiserin bedient die Steine und sorgt so für eine Verbindung zwischen ihr und den Truppen der Zan'thik. Unterbrecht das Signal und bringt ihn dann zum Schweigen.", sourceObjective = "Macht Euch an dem Resonanzkristall der Zan'thik bei den Flüsternden Steinen in Zan'vess zu schaffen, um den Gehilfen Sek'ot zu reizen, und tötet ihn.", progress = "Wissen ist Macht.", completion = "Den Kontakt zu Zan'vess zu verlieren, muss sie weiter in den Verfolgungswahn und Wahnsinn treiben.\n\nGut. Soll sie leiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31511] = { id = 31511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein historischer Moment", description = "Ich trommle die anderen Taurenpilger zusammen und wir reisen gemeinsam ins Tal.\n\nTrefft mich am Tor der Himmlischen Erhabenen im Süden des Kun-Lai-Gipfels und sprecht dort mit mir.", sourceObjective = "Sprecht mit Sonnenläufer Dezco am Tor der Himmlischen Erhabenen.", completion = "Willkommen im Schrein der Zwei Monde, Reisender.\n\nIch weiß, die Erhabenen haben Euch geschickt, aber zuerst haltet einen Moment inne und erkundet die Stadt.\n\nWillkommen in unserem Tal.", sourceObjectiveStatus = "unverified-source-field" }
quests[31512] = { id = 31512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein historischer Moment", description = "Die Himmlischen Erhabenen gewähren uns erneut Zugang zum Tal! Das wird ein unvergesslicher Anblick sein.\n\nWir sollten keine Zeit verlieren. Geht zum Tor der Himmlischen Erhabenen im Süden des Kun-Lai-Gipfels und sprecht dort mit mir.", sourceObjective = "Sprecht mit Anduin Wrynn am Tor der Himmlischen Erhabenen.", completion = "Willkommen im Schrein der Sieben Sterne, Reisender.\n\nIch wünschte, Ihr könntet uns bessere Neuigkeiten mitteilen, {class}, aber die Situation hier im Tal ist äußerst düster.\n\nEs gibt viel zu tun, aber ruht Euch zunächst aus und erkundet die Stadt.\n\nWillkommen in unserem Tal.", sourceObjectiveStatus = "unverified-source-field" }
quests[31513] = { id = 31513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klingen des Gesalbten", description = "Das Problem mit dem Scharlachroten Kreuzzug ist, dass seine Kreuzfahrer selbst nach dem Tod immer wiederkehren.\n\nHinter diesen Wiederbelebungen steckt die Hochinquisitorin Weißsträhne. Ihr Tod wäre das Ende des Kreuzzuges.\n\nUm sie endgültig ins Jenseits zu schicken, benötigen wir zwei legendäre Schwerter, jedes von ihnen mit einer lange verschollenen Geschichte.\n\nZum Glück für mich... äh, ich meine uns... befinden sich diese Klingen des Gesalbten hier irgendwo im Kloster.\n\nFindet sie und stoßt sie in Weißsträhnes Leichnam, nachdem Ihr sie getötet habt. Dadurch ist ihr Tod endgültig.", sourceObjective = "Findet die zwei Klingen des Gesalbten.", progress = "<Nachdem Ihr das eine Schwert eingesammelt habt, wendet Ihr Euch der Suche nach dem zweiten zu.>\n\n<Auf der Statue hinter dem Schwert befindet sich eine Inschrift: \"Die Hand der Vorsehung\".>", completion = "<Die zweite gesalbte Klinge schwebt vor der nassen Statue. Dampf steigt vom Schwert auf.>\n\n<Ihr habt das ungute Gefühl, dass die Hand der Vorsehung auf Euch gewartet hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31514] = { id = 31514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und zum Staub werdet Ihr zurückkehren", description = "<Ihr nehmt die zweite Klinge des Gesalbten in die Hand und fühlt, wie Euch die Kraft der beiden Schwerter durchströmt.>\n\n<Aber es bleibt noch eins zu tun: Wie Euch die mysteriöse Frau mit der Kapuze erklärte, müssen beide Schwerter in den Leichnam der Hochinquisitorin Weißsträhne gestoßen werden, um den Scharlachroten Kreuzzug ein für alle Mal zu besiegen.>", sourceObjective = "Durchbohrt mit den Klingen des Gesalbten den Leichnam der Hochinquisitorin Weißsträhne, um sie endgültig zu töten.", progress = "<Die Aufgabe ist noch nicht erfüllt. Solange Weißsträhne von den Toten auferstehen kann, ist der Kreuzzug nicht besiegt.>", completion = "Jetzt wo Weißsträhne endgültig tot ist, ist auch der Kreuzzug am Ende. Es ist nur noch eine Frage der Zeit, bis wir seinen Widerstand gebrochen haben werden.\n\nIch danke Euch, {name}. Nicht nur um meiner selbst willen, sondern auch im Namen aller, die diesem fanatischen Hass ausgesetzt waren.\n\nUnd danke auch für die beiden Schwerter. Durch ihr Blut aufs Neue gesalbt, werden sie mir im Kampf gegen Dunkelmeister Gandling in Scholomance gute Dienste leisten.\n\nUnd jetzt möchte ich mich von Euch verabschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31515] = { id = 31515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klingen des Gesalbten", description = "Das Problem mit dem Scharlachroten Kreuzzug ist, dass seine Kreuzfahrer selbst nach dem Tod immer wiederkehren.\n\nHinter diesen Wiederbelebungen steckt die Hochinquisitorin Weißsträhne. Ihr Tod wäre das Ende des Kreuzzuges.\n\nUm sie endgültig ins Jenseits zu schicken, benötigen wir zwei legendäre Schwerter, jedes von ihnen mit einer lange verschollenen Geschichte.\n\nZum Glück für mich... äh, ich meine uns... befinden sich diese Klingen des Gesalbten hier irgendwo im Kloster.\n\nFindet sie und stoßt sie in Weißsträhnes Leichnam, nachdem Ihr sie getötet habt. Dadurch ist ihr Tod endgültig.", sourceObjective = "Findet die zwei Klingen des Gesalbten.", progress = "<Nachdem Ihr das eine Schwert eingesammelt habt, wendet Ihr Euch der Suche nach dem zweiten zu.>\n\n<Auf der Statue hinter dem Schwert befindet sich eine Inschrift: \"Die Hand der Vorsehung\".>", completion = "<Die zweite gesalbte Klinge schwebt vor der nassen Statue. Dampf steigt vom Schwert auf.>\n\n<Ihr habt das ungute Gefühl, dass die Hand der Vorsehung auf Euch gewartet hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31516] = { id = 31516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und zum Staub werdet Ihr zurückkehren", description = "<Ihr nehmt die zweite Klinge des Gesalbten in die Hand und fühlt, wie Euch die Kraft der beiden Schwerter durchströmt.>\n\n<Aber es bleibt noch eins zu tun: Wie Euch die mysteriöse Frau mit der Kapuze erklärte, müssen beide Schwerter in den Leichnam der Hochinquisitorin Weißsträhne gestoßen werden, um den Scharlachroten Kreuzzug ein für alle Mal zu besiegen.>", sourceObjective = "Durchbohrt mit den Klingen des Gesalbten den Leichnam der Hochinquisitorin Weißsträhne, um sie endgültig zu töten.", completion = "Jetzt wo Weißsträhne endgültig tot ist, ist auch der Kreuzzug am Ende. Es ist nur noch eine Frage der Zeit, bis wir seinen Widerstand gebrochen haben werden.\n\nIch danke Euch, {name}. Nicht nur um meiner selbst willen, sondern auch im Namen aller, die diesem fanatischen Hass ausgesetzt waren.\n\nUnd danke auch für die beiden Schwerter. Durch ihr Blut aufs Neue gesalbt, werden sie mir im Kampf gegen Dunkelmeister Gandling in Scholomance gute Dienste leisten.\n\nUnd jetzt möchte ich mich von Euch verabschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31517] = { id = 31517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabaukenkampf", description = "Hier achten wir Stärke, nicht Brutalität. Es ist bedauerlich, dass sich so mancher auf meiner Türschwelle einfindet, dem diese Unterscheidung unklar ist.\n\nIch habe einen solchen Herausforderer abgewiesen. Aus Rache ist er über das Dorf Yinying hergefallen.\n\nGeht nach Yinying, südöstlich des Tempels, und stellt Euch diesem \"Shonuf\".", sourceObjective = "Besiegt Shonuf.", completion = "Ich preise Euren Sieg und danke Euch, dass Ihr mir diesen Grobian vom Hals geräumt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31518] = { id = 31518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal der Ewigen Blüten", description = "Es sind viele Lebensalter vergangen, seit die Tore zum Tal offen standen, {name}.\n\nDas würde ich um alles in der Welt nicht verpassen wollen, und Ihr solltet das auch nicht!\n\nTrefft mich am Südrand des Kun-Lai-Gipfels. Ich werde dort auf Euch warten.", sourceObjective = "Sprecht mit Anduin am Tor der Himmlischen Erhabenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31519] = { id = 31519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Yan-Zhu der Dekantierte", description = "{name}, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in die Brauerei Sturmbräu führen. Aktiviert die Kugel des Herausforderers und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt die Brauerei Sturmbräu im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31520] = { id = 31520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Sha des Zweifels", description = "{name}, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in den Tempel der Jadeschlange führen. Aktiviert die Kugel des Herausforderers und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Tempel der Jadeschlange im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31521] = { id = 31521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichten eines Meisters", description = "Es wird der Tag kommen, an dem Ihr alles gemeistert haben werdet, was wir Euch beizubringen haben. An jenem Tag ist es Zeit für Euch, andere etwas zu lehren. Wenn Ihr unter Beweis gestellt habt, dass Ihr alle Wege gemeistert habt, kommt zurück und redet mit mir.", sourceObjective = "Bereitet Rippchen mit schwarzem Pfeffer und Garnelen, Küstennebelreisnudeln, Fischeintopf nach Moguart, Gedämpfte Krabbe, Chun-Tian-Frühlingsrollen und ein wahnsinniges Brauerfrühstück zu und kehrt dann zur Weiserin der Wege zurück.", completion = "Ihr wart ein sehr guter Schüler. Nun solltet Ihr Euer Wissen an andere weitergeben. Ich hoffe, Ihr redet mit dem Vorratsmeister und nehmt so früh wie möglich einen Lehrling an.", sourceObjectiveStatus = "unverified-source-field" }
quests[31522] = { id = 31522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Sha des Hasses", description = "{name}, Ihr müsst eine abgeklärte Gruppe zusammenstellen und sie ins Shado-Pan-Kloster führen. Aktiviert die Kugel des Herausforderers und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Shado-Pan-Kloster im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31523] = { id = 31523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Xin der Waffenmeister", description = "{name}, Ihr müsst eine geschickte Gruppe zusammenstellen und sie in den Mogu'shanpalast führen. Aktiviert die Kugel des Herausforderers und bereitet Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Mogu'shanpalast im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31524] = { id = 31524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Raigonn", description = "{name}, Ihr müsst eine entschlossene Gruppe zusammenstellen und sie zum Tor der Untergehenden Sonne führen. Aktiviert die Kugel des Herausforderers und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Tor der Untergehenden Sonne im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31525] = { id = 31525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Schwadronsführer Ner'onok", description = "{name}, Ihr müsst eine scharfsichtige Gruppe zusammenstellen und sie zur Belagerung des Niuzaotempels führen. Aktiviert die Kugel des Herausforderers und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Niuzaotempel im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31526] = { id = 31526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Durand", description = "{name}, Ihr müsst eine tapfere Gruppe zusammenstellen und sie in das Scharlachrote Kloster führen. Aktiviert die Kugel des Herausforderers und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Scharlachrote Kloster im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31527] = { id = 31527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Flammenwirker Koegler", description = "{name}, Ihr müsst eine gewitzte Gruppe zusammenstellen und sie in die Tiefen der Scharlachroten Hallen führen. Aktiviert die Kugel des Herausforderers und setzt dem bücherverbrennenden Treiben von Flammenwirker Koegler ein Ende.", sourceObjective = "Schließt die Scharlachroten Hallen im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31528] = { id = 31528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Dunkelmeister Gandling", description = "{name}, Ihr müsst eine furchtlose Gruppe zusammenstellen und sie in die Tiefen von Scholomance führen. Aktiviert die Kugel des Herausforderers und reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt Scholomance im Herausforderungsmodus ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[31529] = { id = 31529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Eindämmung der Shed-Ling", description = "Ich wurde in dieses Tal entsandt, um das Kernland vor allen möglichen Bedrohungen zu verteidigen.\n\nUnd ich habe ein vordringliches Ziel ausgemacht. Die Shed-Ling der Sprungschweife haben sich in die Bergklippen hoch über dem Ackerland eingegraben.\n\nWenn sich niemand um sie kümmert, werden sie sich rasend schnell vermehren und schon bald auf den Feldern unten auftauchen.\n\nSie müssen ausgelöscht werden.", sourceObjective = "Tötet 12 Shed-Ling der Sprungschweife.", completion = "Die Ziele sind ausgelöscht? Gut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31530] = { id = 31530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Ho-zen-Eindämmung", description = "Seit meiner Ankunft hier habe ich die Ho-zen beobachtet. Und das Muster ihrer Aktivitäten im Lager gefällt mir ganz und gar nicht.\n\nIm Schutze der Nacht steigen mehrere Ho-zen vom Berg hinunter in das Ackerland im Tal, um Vorräte zu rauben.\n\nWir müssen diese Diebeszüge aufhalten. Ich habe bei jeder sich mir bietenden Gelegenheit einige von ihnen ausgeschaltet, aber ein Soldat allein ist nicht genug.\n\nIch benötige Eure Hilfe. Tötet ganz einfach so viele Ho-zen wie möglich.", sourceObjective = "Tötet 12 Ho-zen von Kunzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31531] = { id = 31531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Bedrohung aus der Luft", description = "Ich habe ein weiteres, möglicherweise gefährliches Ziel ausgemacht, das wohl den meisten anderen Personen entgangen wäre.\n\nDie Klippensegler über den Hügeln im Osten stellen eine ernsthafte Gefahr dar.\n\nIch konnte beobachten, wie sie sich auf die Felder der Bauern stürzen und Getreide und Samen schnappen, wenn niemand hinschaut.\n\nUm die Höfe zu beschützen, müssen wir einige von ihnen ausschalten.", sourceObjective = "Tötet 12 Klippensegler.", completion = "Ich wusste, dass Ihr diesen Auftrag problemlos erfüllen würdet. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31532] = { id = 31532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: König der Raubvögel", description = "Auf meiner täglichen Routinepatrouille durch die Berge habe ich heute Morgen einen riesigen, weißen Vogel entdeckt, der auf die Felder niederstieß.\n\nEr hat sich ein voll ausgewachsenes Yak gekrallt und ist damit in den Klippen verschwunden.\n\nHeute war es ein Yak, aber morgen könnte es einen Landarbeiter treffen!\n\nWir müssen diesen Vogel ausschalten, bevor er sich ein neues Opfer suchen kann.", sourceObjective = "Tötet den großen Klippenfalken.", completion = "Ihr habt es tatsächlich geschafft, {name}! Ich bin sehr erleichtert, dass das Tal dank Eures Einsatzes wieder sicherer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[31533] = { id = 31533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekte Feder", description = "Diese wunderschöne und makellose Feder ist im ganzen Tal einzigartig.\n\nEs gibt da eine Person, die diese Feder vielleicht sehen möchte.", sourceObjective = "Bringt die Feder zum alten Hügelpranke in seinem Haus oder auf dem Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[31534] = { id = 31534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erste Bräu", description = "Könnt Ihr ein Geheimnis bewahren, {name}?\n\nIch habe mich mit dem Brauen beschäftigt. Ich habe zwar nur diese alte, handgefertigte Brauanlage, aber sie funktioniert noch ganz ordentlich.\n\nUnd ich habe eine Idee für ein neues Braurezept. Allerdings fehlen mir dazu ein paar Zutaten.\n\nIch selbst bin ja leider furchtbar schüchtern, aber ich habe gesehen, wie viele Freunde Ihr schon unter den Leuten hier gefunden habt.\n\nKönntet Ihr nicht vielleicht einige Zutaten von den Bauern für mich besorgen?", sourceObjective = "Besorgt 1 süße Teichmelone von Haohan Lehmkrall, 1 flaumigen Pfirsich von Gina Lehmkrall, 1 Portion schwarze Kirschen von Fischi Rohrroder und 1 roten Rettich von Bauer Fung.", progress = "Ich weiß nicht, wie ich auf die Idee gekommen bin... Vielleicht ist es, weil ich die ganze Zeit auf diese Brauerei starre... Aber ich will das beste Bier des ganzen Tales, nein, von Pandaria brauen!\n\nOh, was für ein naiver Traum, oder?", completion = "Ihr habt sie! Das ist ja wundervoll, {name}!\n\nIch werde so schnell wie möglich mit dem Brauen anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31535] = { id = 31535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen der Speisekammer", description = "Aus ganz Pandaria kommen die Leute, um von der Familie Eisentatz kochen zu lernen. Wir sind sehr stolz darauf, die besten Köche zu stellen, und auch darauf, unser Wissen weitergeben zu können. Aus diesem Grund verlangen wir nur sehr wenig für unseren Kochunterricht.\n\nDas bedeutet jedoch auch, dass wir oft einen Mangel an Zutaten für die Unterrichtsstunden haben. Wärt Ihr bereit, etwas der Schule zu spenden, um den Schülern zu helfen, die nicht genug Geld haben?", sourceObjective = "Bringt Nam Eisentatz ein Bündel mit Zutaten. Bündel mit Zutaten werden mithilfe von Behältern hergestellt, die von Händler Cheng verkauft werden.", progress = "Es ist schwierig, kochen zu lernen, wenn man keine Zutaten hat.", completion = "Wir wissen Eure Hilfe sehr zu schätzen. Dies ist für einige unserer Schüler eine große Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31536] = { id = 31536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konservierung der Frische", description = "Damit Kochzutaten so frisch wie möglich bleiben, müssen sie stets richtig gelagert werden. Zum Glück verkauft Händler Cheng dort drüben gute Behälter. Ich will Euch ja nur ungern eine so anspruchslose Aufgabe auftragen, aber könntet Ihr vielleicht einen leeren Tigerfleischkorb für mich kaufen?", sourceObjective = "Bringt Nam Eisentatz einen leeren Tigerfleischkorb.", progress = "Zutaten verderben, wenn sie nicht korrekt gelagert werden.", completion = "Ah, das ist gut. Jetzt werden diese Zutaten frisch bleiben, bis wir bereit sind zu kochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31537] = { id = 31537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellas Kostprobe", description = "So, jetzt ist mein Bräu endlich fertig. Aber um zu wissen, ob es auch etwas taugt, muss jemand es kosten.\n\nWürdet Ihr vielleicht mein Bräu nehmen und herausfinden, was die Leute in Halbhügel dazu sagen?\n\nIch... Ich selbst traue mich nicht.", sourceObjective = "Fragt Jogu den Betrunkenen, Bobo Eisentatz, Bauer Yoon und Nana Lehmkrall, was sie von Ellas Bräu halten.", completion = "Wirklich? Das haben sie wirklich gesagt? Unglaublich!", sourceObjectiveStatus = "unverified-source-field" }
quests[31538] = { id = 31538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein guter Tropfen", description = "Jetzt fehlt nur noch eine Person, die mein Bräu kosten muss.\n\nUnd diese Person soll weit gereist und Getränke in der ganzen Welt verkostet haben.\n\nEr ist gerade vor Ort und ich würde gern wissen, was er von meinen Fähigkeiten hält.", sourceObjective = "Bittet Chen Sturmbräu, Ellas Bräu zu kosten.", progress = "Man kann immer etwas besser machen.", completion = "Ihr wollt mich doch nicht etwa auf den Arm nehmen, oder, {name}? Wenn er das wirklich gesagt hat, heißt das... dass ich etwas vom Brauen verstehe!\n\nIch danke Euch, {name}. Ihr habt mir wirklich geholfen, zu etwas Selbstvertrauen zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31539] = { id = 31539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Schönheit", description = "Wir leben in einer Welt der Magie. Die wenigen unter uns, die über eine große Begabung verfügen, können die Dinge, die wir fertigen, mit dieser Magie versehen und ihnen Kräfte verleihen. Solche Dinge werden hoch geschätzt.\n\nDoch die noch größere Ausnahme sind die Personen, die Dinge schaffen, die über mehrere Zeitalter hinweg geschätzt werden - nicht weil sie über Kräfte verfügen, sondern wegen ihrer herausragenden Schönheit.\n\nDer Tempel der Jadeschlange hat uns mit solch einem Werk beauftragt, und ich glaube, Ihr seid einer der Würdigsten unter uns. Nehmt Ihr den Auftrag an?", sourceObjective = "Fertigt ein Auftragsgemälde an und bringt es zu Tintenmeister Wei im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenkundemenü unter \"Quests\".", progress = "Dies ist ein großes Projekt. Es wird viel Zeit und Mühe in Anspruch nehmen, selbst für jemanden, der so talentiert ist wie Ihr.", completion = "Das... Das übersteigt meine kühnsten Erwartungen. Generationen werden sich daran erfreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31540] = { id = 31540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stäbe für das Tiankloster", description = "Wie es scheint, werden im Tiankloster dieses Jahr viele Mönche ausgebildet. Wir haben einen riesigen Auftrag für Stäbe erhalten. Und mit riesig meine ich wirklich RIESIG.\n\nKönntet Ihr einen Teil des Auftrags übernehmen? Das würde ich sehr zu schätzen wissen. Ihr werdet natürlich die Belohnungen für Euren Anteil erhalten.", sourceObjective = "Fertigt 3 Geistereisenstäbe und 2 Regenmohnstäbe. Bringt sie zu Tintenmeister Wei im Arboretum im Jadewald.", progress = "So viele Stäbe?! Wie viele Mönche haben die denn?!", completion = "Tolle Handwerkskunst. Die Mönche werden sehr angetan sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[31541] = { id = 31541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Jade gemeißelt", description = "Meister Kwang ist einer der größten Dichter unserer Zeit. Er hat ein wunderschönes Gedicht geschrieben, und eine Händlerin in Halbhügel hätte gerne diese Worte in Stein gemeißelt, um sie stolz in ihrem Zuhause ausstellen zu können. Sie will, dass jemand mit den besten Fähigkeiten damit beauftragt wird. Würdet Ihr diesen Auftrag annehmen?", sourceObjective = "Fertigt eine gravierte Jadescheibe und bringt sie zu Tintenmeister Jo Po im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenmenü unter \"Quests\".", progress = "Wie läuft es?", completion = "Wunderschön. Das wird mit Sicherheit Gefallen finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31542] = { id = 31542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleischfarbene Tinte", description = "Die Kalligraphie ist ein uralter Brauch in Pandaria. Ich arbeite an einem Werk über einen uralten Krieg, und ich suche nach einer Tinte, die für das Thema geeignet ist.\n\nIch habe wirklich fast überall nach dem richtigen Farbton gesucht, aber ich kann ihn einfach nirgends finden. Fällt Euch vielleicht eine Möglichkeit ein, an die Farbe zu kommen, die ich benötige?", sourceObjective = "Um die von Tintenmeister Glenzu gewünschte Farbe zu erhalten, sind Pigmente aus einer ungewöhnlichen Quelle erforderlich. Seine Beschreibung lässt vor Eurem geistigen Auge die Farbe des Blutes erscheinen -der von Tigerblut, um genau zu sein...\n\n Stellt 5 Einheiten Fleischfarbene Tinte her. Das Rezept findet Ihr in Eurem Inschriftenkundemenü unter \"Quests\".", progress = "Ich kann einfach nicht die richtige Farbe finden!", completion = "Wo habt Ihr... Wie habt Ihr... Das ist ja perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31543] = { id = 31543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Porträt einer Dame", description = "Viele große Kunstwerke sind das Ergebnis einer großen Liebe. Ein Händler in Halbhügel würde gerne ein Porträt als Geburtstagsgeschenk für seine geliebte Frau anfertigen lassen. Wollt Ihr diesen Auftrag annehmen?", sourceObjective = "Malt ein Porträt von Madame Goya und bringt es zu Tintenmeister Glenzu im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenmenü unter \"Quests\".", progress = "Es ist wunderschön, einen so verliebten Mann zu sehen.", completion = "Ein wunderschönes Gemälde.", sourceObjectiveStatus = "unverified-source-field" }
quests[31544] = { id = 31544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tribut den Toten", description = "Alles hat einmal ein Ende. Sogar das Leben eines guten Mannes. Eine Familie am Kun-Lai hat ein Monument für ihren geliebten Patriarchen, der vor Kurzem aus dem Leben geschieden ist, in Auftrag gegeben. Nehmt Ihr den Auftrag an?", sourceObjective = "Fertigt einen Beschriebenen Monumentstein an und bringt ihn zu Tintenmeister Jo Po im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenkundemenü unter \"Quests\".", progress = "Die Toten zu respektieren, ist Teil unserer Traditionen.", completion = "Ein großartiges Werk zu Ehren eines großartigen Mannes.", sourceObjectiveStatus = "unverified-source-field" }
quests[31545] = { id = 31545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schönen Dinge im Leben", description = "Die Pandarianische Schatzsuchervereinigung ist daran interessiert, fachmännisch gefertigte Ware von fähigen Juwelenschleifern, wie Ihr es seid, zu kaufen. Die Artikel werden katalogisiert, und die außergewöhnlichsten Schliffe werden in einer geheimen Schatzkammer aufbewahrt, während der Rest verkauft wird, um unsere Kasse aufzufüllen.\n\nUnser Ziel ist es, schließlich eine einzigartige Kollektion für ein besonderes Ereignis zu kreieren.", sourceObjective = "Bringt die angeforderten Waren zu einem Mitglied der Pandarianischen Schatzsuchervereinigung im Tal der Ewigen Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31548] = { id = 31548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht ins Tal und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Kampf mit einem Haustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31549] = { id = 31549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Shelby Steinsplint auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Shelby Steinsplint die Stallmeisterin aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31550] = { id = 31550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", completion = "Aha... eine hervorragende Wahl. Ihr seid auf dem besten Weg, Euch ein tolles Team aufzubauen!\n\nDenkt daran: Ihr habt die Möglichkeit, jedes Haustier zu fangen, gegen das Ihr kämpfen könnt, also holt Euch im Laufe Eurer Abenteuer so viele wie möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31551] = { id = 31551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31552] = { id = 31552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in den Wald und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Kampf mit einem Haustier.", completion = "Gut gemacht, {name}! Ihr könnt mit diesen Haustieren besser umgehen, als ich dachte!", sourceObjectiveStatus = "unverified-source-field" }
quests[31553] = { id = 31553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Seriadne auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Seriadne die Stallmeisterin aufsucht.", completion = "Jetzt strotzen Eure Haustiere ja nur so vor Gesundheit, {name}. Denkt daran, Ihr könnt all Eure Haustiere jederzeit heilen und wiederbeleben lassen, indem Ihr einen Stallmeister aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31554] = { id = 31554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Seriadne auf, um Eure Haustiere zu heilen und wiederzubeleben.Ihr erlernt:", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Seriadne die Stallmeisterin aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
