quests[31569] = { id = 31569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31570] = { id = 31570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31571] = { id = 31571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in den Wald und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Kampf mit einem Haustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31572] = { id = 31572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Shoja'my auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Shoja'my die Stallmeisterin aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31573] = { id = 31573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in den Wald und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Kampf mit einem Haustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31574] = { id = 31574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Seikwa auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Seikwa die Stallmeisterin aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31575] = { id = 31575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31576] = { id = 31576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Erfahrungen", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in den Wald und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", sourceObjective = "Gewinnt einen Kampf mit einem Haustier.", completion = "Gut gemacht, {name}! Ihr könnt mit diesen Haustieren besser umgehen, als ich dachte!", sourceObjectiveStatus = "unverified-source-field" }
quests[31577] = { id = 31577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Wege der Besserung", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unseren Stallmeister Morganus auf, um Eure Haustiere zu heilen und wiederzubeleben.", sourceObjective = "Heilt Eure Haustiere vollständig, indem Ihr Morganus den Stallmeister aufsucht.", completion = "Jetzt strotzen Eure Haustiere ja nur so vor Gesundheit, {name}. Denkt daran, Ihr könnt all Eure Haustiere jederzeit heilen und wiederbeleben lassen, indem Ihr einen Stallmeister aufsucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31578] = { id = 31578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hab' eins!", description = "So weit, so gut, {name}! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", sourceObjective = "Fangt ein Kampfhaustier.", completion = "Aha... eine hervorragende Wahl. Ihr seid auf dem besten Weg, Euch ein tolles Team aufzubauen!\n\nDenkt daran: Ihr könnt jedes Haustier fangen, gegen das Ihr kämpfen könnt, also holt Euch im Laufe Eurer Abenteuer so viele wie möglich.", sourceObjectiveStatus = "unverified-source-field" }
