quests[31655] = { id = 31655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mishi Tracking 1" }
quests[31656] = { id = 31656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung im Süden", description = "Nun, da das Sha des Hasses tot ist, ist die größte Bedrohung dieses Landes gebannt. Unsere Reisen entlang der südlichen Grenzen haben jedoch deutlich gemacht, dass die Mantisstreitkräfte in der Schreckensöde in Bewegung sind und wahrscheinlich nicht mehr lange zurückgehalten werden können.\n\nFalls Ihr den Shado-Pan weiterhin helfen wollt, würde ich empfehlen, Euch bei Bogenmeisterin Li auf dem Schlangenrücken vorzustellen. Sie bewacht die große Mauer, die das Grauen der Schreckensöde von unseren üppigen Ländern im Osten trennt.", sourceObjective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Ich glaube, da seid Ihr der Erste.\n\nFreut mich, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31660] = { id = 31660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Schwarm nicht angemessen", description = "Frisch geschlüpfte Mantis werden nur von zwei Instinkten getrieben: Töten und fressen. Sie gehen aufeinander los und verschlingen die Schwachen. Nur die Stärksten wachsen heran.\n\nDie, die während eines Schwarms schlüpfen - die Schwarmgeborenen - werden stattdessen auf unsere Feinde losgelassen.\n\nDie Schwarmgeborenen in den Gelegen von Shek'zeer wurden verderbt. Sie werden in Schatten und Alpträume hineingeboren. Getrieben vom Schrecken, nicht vom Hunger.\n\nSie sind dem Schwarm nicht angemessen. Sie müssen geläutert werden.", sourceObjective = "Tötet 30 Schwarmgeborene der Shek'zeer in den Gelegen von Shek'zeer.", completion = "Ihre Eier hätten noch zehn weitere Jahre in der Wärme der Sonne schwelgen und der Melodie von einer Million Flügeln lauschen sollen.\n\nDie Kaiserin wird für ihre Verbrechen bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31661] = { id = 31661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Quelle furchtbarer Macht", description = "<Die Gelegehüter der Shek'zeer scheinen diese blendenden weißen Kristalle als magische Fokusse zu verwenden. Ihr blickt hinein und seht, wie sich dicke Schwaden schwarzen Rauchs in seiner Mitte drehen. Einer der Arbeiter in Klaxxi'vess weiß vielleicht mehr über dieses Material und warum es so viel davon in der Öde gibt.>", sourceObjective = "Bringt den Sha-besessenen Kristall zu Bernschmied Zikk in Klaxxi'vess.\n\nBereitgestellter Gegenstand:", completion = "Habt Ihr irgendeine Ahnung, was das ist? Es ist Bern!\n\nAber er ist mit Angst verseucht.\n\nVon einem Außenseiter wie Euch erwarte ich allerdings nicht, dass er die daraus erwachsenden Folgen versteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31664] = { id = 31664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quest eines Anglers", description = "Dieses Tagebuch steckt voller verschwommener Erinnerungen an Nat Pagles große Abenteuer. Es zu lesen wird ohne Zweifel einen wertvollen Einblick in die Angelkunst bieten.", sourceObjective = "Lest Nats Angeltagebuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31665] = { id = 31665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Gemüsomat 4000 umgewandelt" }
quests[31666] = { id = 31666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Wind-Reaver's Dagger" }
quests[31668] = { id = 31668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfallereignis" }
quests[31669] = { id = 31669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kohlprüfung", description = "Großvater hat immer gesagt, dass ein wahrer Bauer an der Qualität seines Kohls gemessen werden kann. Jedes Mal, wenn ein neuer Bauer in die Stadt kam, kaufte er ein paar Kohlköpfe, um herauszufinden, was sie darüber wussten.\n\nJetzt bin ich der neue Bauer und dies ist meine große Chance, mich unter Beweis zu stellen. Könntet Ihr bitte ein wenig Kohl für mich anpflanzen?", sourceObjective = "Pflanzt einen Grünkohl auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Wartet nur, bis sie diesen Kohl probieren. Dann werden sie erkennen, dass ich ein wahrer Bauer bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[31670] = { id = 31670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlockende Karotten", description = "Großvater hat immer gesagt: \"Karotten sind nichts als ein Willkommensgeschenk für Shed-Ling\". Ich glaube nicht, dass er je auch nur eine einzige Karotte angepflanzt hat.\n\nAusnahmsweise stimme ich einmal nicht mit Großvater überein. Ich gehe gerne Risiken ein. Außerdem esse ich auch gerne Karotten.\n\nIch gehe gern Risiken ein, wenn ich Karotten esse.\n\nKönntet Ihr ein paar Samen besorgen und eine Karotte für mich anbauen?", sourceObjective = "Pflanzt eine saftigleckere Karotte auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Ich kann es kaum abwarten, bis die Karotten reif sind. Vielen Dank, {name}. Bis morgen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31671] = { id = 31671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühlingszwiebeln? Warum nicht?", description = "Ich habe Haohan sagen hören, dass er heute Frühlingszwiebeln anbauen will. Ich bin mir zwar nicht sicher, ob heute der beste Tag dafür ist, aber ich gehe davon aus, dass er schon weiß, was er tut. Schließlich ist er der Vorsitzende des Bundes der Ackerbauern.\n\nKönntet Ihr eine Frühlingszwiebel für mich pflanzen?", sourceObjective = "Pflanzt eine Frühlingszwiebel auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Ich kann die Frühlingszwiebeln bereits von hier riechen und freue mich schon, sie morgen zu ernten und zu verkaufen. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[31672] = { id = 31672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Duft des Kürbisses", description = "Auf dem Markt habe ich das Gerücht gehört, dass Gina Lehmkrall den Duft von Kürbisblüten liebt. Vielleicht würde sie mich ja ein wenig häufiger besuchen kommen, wenn ich auf meinem Hof ein paar Kürbisse anbaue.\n\nKönntet Ihr bitte einen Kürbis für mich pflanzen?", sourceObjective = "Pflanzt einen Mogukürbis auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Und jetzt werden wir darauf lauern, dass er reif wird...\n\nOh, entschuldigt, das hat sich vielleicht ein wenig gruselig angehört. Vergesst, dass ich das gesagt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31673] = { id = 31673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ja, ja, so rot - rot - rot blüht der Blütenlauch...", description = "Großvater hat mir mal erzählt, dass der Geruch von Lauch Krokilisken vom Grundstück fernhält. Da muss was Wahres dran gewesen sein, denn auf seinen Feldern wuchs immer Lauch und ich habe in der Umgebung seines Hofes nie auch nur einen einzigen Krokilisken gesehen.\n\nWir sind hier ziemlich weit vom Wasser entfernt... aber ich denke, man kann nie sicher genug sein.", sourceObjective = "Pflanzt eine Stange Rotblütenlauch auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Ich möchte mal einen Krokilisken sehen, der es jetzt noch wagt, meinen Hof anzugreifen!\n\nHa HA!", sourceObjectiveStatus = "unverified-source-field" }
quests[31674] = { id = 31674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hat die schönsten rosa Rüben im ganzen Land?", description = "Der alte Hügelpranke hat mit mir gewettet, dass auf meinem Land keine rosa Rüben wachsen werden.\n\nAber ich werd's ihm zeigen. Auf meinem Land werden die größten, rosansten Rüben wachsen, die der alte Kauz je gesehen hat.", sourceObjective = "Pflanzt eine rosa Rübe auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", progress = "Der alte Hügelpranke... so ein Blödmann.", completion = "Hah! Der alte Hügelpranke wird Augen machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31675] = { id = 31675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heilkraft weißer Rüben", description = "Großvater hat oft gesagt: \"Man soll sein Haus sauber halten, aber sein Feld noch viel sauberer\". Das hört sich vielleicht nach einem Witz an, aber er hatte schon recht.\n\nWenn man Gemüse erntet, bleiben oft noch Wurzelteile zurück, die die Erde vergiften... doch eine schöne, große, weiße Rübe ist das perfekte Gegenmittel dafür. Könntet Ihr vielleicht eine für mich anpflanzen?", sourceObjective = "Pflanzt eine weiße Rübe auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", completion = "Schaut Euch nur diese Erde an. Sie glänzt ja beinahe.\n\nGroßvater wäre so stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[31676] = { id = 31676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Rache", description = "Ich kann hören, wie sie vor Wut aufschreien... die Geister der Gurthanimogu, die ich vor so langer Zeit tötete. Auf der Suche nach Rache irren sie auf dieser zerstörten Terrasse umher.\n\nWenn sie mich in meinem jetzigen Zustand vorfinden, werde ich nicht stark genug sein, sie abzuwehren. Erregt ihre Aufmerksamkeit und beseitigt sie.\n\nBringt zu Ende, was ich begonnen habe, und ich werde Euch sagen, wer ich bin.", sourceObjective = "Tötet 6 rachsüchtige Gurthanigeister auf der Terrasse von Gurthan.", completion = "Die Mogu sind ein gemeinsamer Feind von uns. Und vielleicht gibt es noch andere.\n\nWir werden sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31677] = { id = 31677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Asche des Kriegsmeisters", description = "<Kil'ruk der Windschnitter besiegte Kriegsherr Gurthan bereits vor Jahrhunderten, doch der Geist des Mogubestienmeisters sucht noch immer die Ruinen seiner alten Festung heim.\n\nWenn Ihr den Klaxxi beweisen könnt, dass Ihr diesen Geist bezwungen habt, könntet Ihr in ihrer Gunst steigen.>", sourceObjective = "Bringt die Asche von Kriegsherr Gurthan zu Kil'ruk dem Windschnitter in Klaxxi'vess.\n\nBereitgestellter Gegenstand:", completion = "Gurthan war ein Feigling, der Bestien ausgebildet hat, um für ihn zu kämpfen, und als sein Tod nahte, entschied er sich dazu, seinen Willen in einer Urne aufzubewahren.\n\nJetzt haben wir das Vergnügen, ihn so oft töten zu können, wie wir wollen.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31679] = { id = 31679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Reichweite ausbauen", description = "Die Klaxxi'va hören noch einen Getreuen. Seine Schreie sind schwach und verlieren sich in der Dunkelheit.\n\nDas Signal muss verstärkt werden.\n\nEs gibt einen Turm in der Bernscheinkuhle, der schon seit vielen Jahren verstummt ist. Er muss singen, Die Klaxxi verlangen es!\n\nDieses Mal begleite ich Euch. Ihr werdet mir helfen, ihn zu reparieren.\n\nNehmt den Resonanzkristall und trefft mich in der Kuhle.", sourceObjective = "Aktiviert das resonierende Signal in der Bernscheinkuhle.", completion = "Gut, dass Ihr rechtzeitig gekommen seid.\n\nDie Klaxxi'va singen jetzt zu den Getreuen. Sie werden bald wissen, wohin sie Euch schicken sollen. Für den Moment gibt es jedoch andere Aufgaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[31680] = { id = 31680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuld und Sühne", description = "Am Stechenden Pfad befinden sich junge Kyparibäume. Die Kaiserin entzieht den Schösslingen viel zu früh ihre Energie, Fremdling. Sie müssen erst wachsen, bevor der Bern entnommen werden kann.\n\nDie Klaxxi'va verlangen, dass dieses Verbrechen bestraft wird! Es wird ihnen gefallen, wenn Ihr den Tod auf die Bernernter der Ik'thik niederregnen lasst.", sourceObjective = "Tötet 8 Bernernter der Ik'thik auf dem Stechenden Pfad.", progress = "Wurden die Ernter bestraft?", completion = "Die Klaxxi sind zufrieden mit unserer Arbeit, Fremdling. Ihr habt Euch als nützlicher herausgestellt, als wir angenommen hatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31681] = { id = 31681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je älter, desto besser", description = "Es ist ein Verbrechen, die jungen Bäume abzuernten, doch den Bern zu verschwenden ist eine noch viel größere Schandtat.\n\nFrischer Bern ist nicht so wirkungsvoll, doch die Klaxxi brauchen ihn, um den Kampf fortführen zu können. Wir werden ihnen mehr davon bringen und sie werden mich mit Dank überhäufen!\n\nSammelt den frischen Bern. Wir lagern ihn ein, bis er lange genug gereift ist, um verzehrt zu werden.", sourceObjective = "Sammelt 7 mit Bern gefüllte Gläser von den Bernsammlern auf dem Stechenden Pfad.", progress = "Ich würde ja mit Euch gehen, um Bern zu sammeln, aber meine Talente finden hier besseren Einsatz.", completion = "Selbst roher Bern wird uns nützlich sein. In Zeiten wie diesen können wir es uns nicht leisten, wählerisch zu sein.\n\nDie Klaxxi'va werden sich freuen, dass ich daran gedacht habe. Ich werde ihnen sagen, dass Ihr mir geholfen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[31682] = { id = 31682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemals wieder am Meer", description = "Die Klaxxi'va haben zu mir gesprochen, Fremdling. Der Getreue war im Salzigen Schlick verborgen, doch inzwischen hat die Tarnung versagt.\n\nDie Echsenmänner haben ihn umstellt. Er darf ihnen nicht in ihre schuppigen Hände fallen.\n\nIhr werdet ihn finden; Ihr werdet ihn erwecken. Kehrt nicht ohne ihn zurück!\n\nFür diese Tat werden uns Die Klaxxi dankbar sein.", sourceObjective = "Benutzt die Stimmgabel der Klaxxi bei den meergepeitschten Felsen, um den Getreuen zu erwecken.", completion = "Was... was für eine Kreatur seid Ihr?\n\nWie habt Ihr mich aufgeweckt?", sourceObjectiveStatus = "unverified-source-field" }
quests[31685] = { id = 31685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal der Vier Winde", description = "Yarr, der Jadewald wird gerade mit Hochdruck umgebaut, aber das Tal der Vier Winde ist reif zum Entdecken. Sprecht mit mir, wenn Ihr gehen wollt, und ich kann Euch dahin bringen wohin Ihr wollt. Sprecht mit meinem Kumpel auf der anderen Seite, um was zu bekommen, das Euch auf der Reise hilft.", sourceObjective = "Teleportiert Euch ins Tal der Vier Winde und sprecht mit dem Gefreiten Tim P. Orär.", sourceObjectiveStatus = "unverified-source-field" }
quests[31687] = { id = 31687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sik'thik ausdünnen", description = "Trotz all unserer Bemühungen, die Mantis in der Schreckensöde zu halten, haben einige unsere Verteidigung durchbrochen. Anscheinend wollen sie zum Niuzaotempel. Meine Männer haben versucht, ihre Präsenz im Westen, bei Sik'vess, auszulöschen. Ohne Erfolg. Wenn Ihr auch nur halb so <ein/eine:c> {class} seid, wie Taran behauptet, habt Ihr vielleicht mehr Erfolg.\n\nGeht nach Westen und tötet alle Mantis der Sik'thik, die Ihr finden könnt. Und denkt daran: Dies ist nicht der richtige Zeitpunkt, Gnade walten zu lassen. Im Tempel sind Leben, die ganz von uns abhängen.", sourceObjective = "Tötet 12 Mantis der Sik'thik.", completion = "Die Mantis sind unerbittlich. Zu unserem Glück übersteigt Eure Verbissenheit selbst die ihre.\n\nEs ist gut, dass Ihr diese Wege beschreitet, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31688] = { id = 31688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Rastlosen Leng", description = "Einer meiner besten Späher, der rastlose Leng, ist während einer Mission auf der anderen Seite von Sik'vess verschollen. Ich hoffe, dass man ihn gefangen genommen und nicht getötet hat, aber da die Mantis so schwer Sha-verseucht sind, ist das nicht sehr wahrscheinlich.\n\nKönntet Ihr trotzdem die Käfige bei Sik'vess durchsuchen? Ich schulde ihm eine gründlichere Suchaktion als diese, aber ich kann keine Männer entbehren, ohne dass unsere südlichen Verteidigungslinien versagen.\n\nBitte, {class}, selbst wenn er sein Leben ausgehaucht hat, findet ihn, damit ich sein Schicksal in Erfahrung bringen kann.", sourceObjective = "Durchsucht die Käfige der Sik'thik nach dem rastlosen Leng.", completion = "Leng hat mir von Euren Heldentaten berichtet. Er steht in Eurer Schuld, genauso wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31689] = { id = 31689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Furchtverschworenen", description = "Die Klaxxi sehen weit und hören viel. Sie haben ihre Einsichten mit mir geteilt.\n\nDie Vor'thik heißen das Sha willkommen und benutzen seine Macht, um ihren Vormarsch in diesem falschen Schwarm zu stützen. Ihre Krieger nehmen verderbten Bern zu sich und nennen sich Furchtverschworene.\n\nSie haben keine Zukunft. Sie sind Unrat, der entfernt werden muss.\n\nUnd IHR werdet diesen Vorgang für uns in Gang setzen, wenn Ihr Kypari Vor erreicht.", sourceObjective = "Tötet 6 Furchtverschworene der Vor'thik bei Kypari Vor.", completion = "In disziplinierten Händen ist der Speer die perfekte Waffe. Nur ein Schwächling würde ihn mit Magie belegen.\n\nUnd wir haben keinen Bedarf an Schwächlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31690] = { id = 31690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschrifteter Tigerstab", description = "So mächtig er auch ist, wisst Ihr doch, dass Ihr diesem Stab eines Tages entwachsen werdet. Wenn diese Zeit gekommen ist, hätte einer der Tintenmeister im Arboretum sicherlich Interesse daran, ihn Euch abzunehmen.", sourceObjective = "Bringt Euren beschrifteten Tigerstab zu Tintenmeister Glenzu im Arboretum.", sourceObjectiveStatus = "unverified-source-field" }
quests[31691] = { id = 31691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschrifteter Kranichstab", description = "So mächtig er auch ist, wisst Ihr doch, dass Ihr diesem Stab eines Tages entwachsen werdet. Wenn diese Zeit gekommen ist, hätte einer der Tintenmeister im Arboretum sicherlich Interesse daran, ihn Euch abzunehmen.", sourceObjective = "Bringt Euren beschrifteten Kranichstab zu Tintenmeister Jo Po im Arboretum.", sourceObjectiveStatus = "unverified-source-field" }
quests[31692] = { id = 31692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschrifteter Schlangenstab", description = "So mächtig er auch ist, wisst Ihr doch, dass Ihr diesem Stab eines Tages entwachsen werdet. Wenn diese Zeit gekommen ist, hätte einer der Tintenmeister im Arboretum sicherlich Interesse daran, ihn Euch abzunehmen.", sourceObjective = "Bringt Euren beschrifteten Schlangenstab zu Tintenmeister Wei im Arboretum.", sourceObjectiveStatus = "unverified-source-field" }
quests[31693] = { id = 31693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julia Stevens", description = "Ihr wollt es also noch mal mit mir aufnehmen?", sourceObjective = "Besiegt Julia Stevens in einem Haustierkampf.", completion = "Autsch, Ihr seid wirklich ein guter Haustiertrainer! Ich schätze, damit bildet Ihr die Ausnahme.", sourceObjectiveStatus = "unverified-source-field" }
quests[31694] = { id = 31694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hisingen Blues" }
quests[31695] = { id = 31695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter der Mauer", description = "Wir haben Nachricht davon erhalten, dass die Shado-Pan mit einem Gegenangriff auf die Tonlongsteppe begonnen haben. Es hört sich an, als wollten sie dem Ursprung der Yaungolinvasion auf den Grund gehen.\n\nDie Pandaren haben seit Tausenden von Jahren keine Streitkräfte in die Tonlongsteppe geführt. Die Shado-Pan sind stark und mutig, aber sie sind auch stolz und nur wenige. Sie werden die Hilfe von Helden wie Euch benötigen. Könnt Ihr durch das Tor von Winterblüte im Nordwesten reisen, um die Anführer der Shado-Pan zu finden und ihnen Eure Hilfe und Erfahrung anzubieten?", sourceObjective = "Sprecht mit Taran Zhu am Außenposten Longying in der Tonlongsteppe.", completion = "Willkommen in der Tonlongsteppe. Wenn Ihr schon darauf besteht, Euch in die dunkelsten Winkel Pandarias zu wagen, dann könnt Ihr Euch dabei auch wenigstens nützlich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31698] = { id = 31698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Bestand ausdünnen", description = "Die letzten Winter waren sehr mild und das Ergebnis dieses Umstands ist, dass die Population wilder Tiger auf der Windwärtsinsel praktisch explodiert ist.\n\nDiese unzähmbaren Kreaturen haben fast alles Wild in der Gegend ausgerottet und jüngst damit begonnen, die Wolkenschlangennester zu überfallen.\n\nDadurch gedeihen die Tiger wie nie zuvor, während die Wolkenschlangen dahinschwinden.\n\nFalls wir nicht vorsichtig sind, könnten die Raubkatzen sie komplett ausrotten.\n\nWir müssen die Tigerpopulation ausdünnen, {race}.", sourceObjective = "Tötet 8 Windwärtstiger oder Windwärtsalphatiere.", completion = "Ihr habt getan, wie Euch aufgetragen wurde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31699] = { id = 31699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldgeistphobie", description = "Ach, du meine Güte... Wie soll ich denn jetzt alle meine Aufgaben erledigen?\n\nAusbilder Himmelsdorn hat mir aufgetragen, ein paar Tiger auf der Windwärtsinsel zu jagen, aber ich habe gehört, dass die ganze Gegend von Waldgeistern nur so wimmelt!\n\nIgitt! Ich hasse Waldgeister! Da läuft es mir eiskalt den Rücken hinunter!\n\nSie sind so klein und... und... sie springen einen an und... und... sie haben so kleine, kalte, tote Stockhändchen!\n\nIgittigitt! Ihr müsst mir helfen, {name}. Macht sie weg! Bitte!", sourceObjective = "Tötet 7 Schattenfeetrickster.", completion = "Ihr habt die Waldgeister zurechtgewiesen, {name}. Sie sollten für eine Weile keinen Ärger mehr bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[31700] = { id = 31700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So wird ein Schuh draus...", description = "Ich verabscheue Waldgeister! Einmal ist mir einer von diesen garstigen Mistkerlen den ganzen Tag lang gefolgt, hat mir Dreck in meinen Tee gestreut und Käfer ins Haar gesetzt.\n\nGanz ehrlich, wer macht sowas!?\n\nNun, ich denke, dass es Zeit für eine kleine Revanche ist. Wisst Ihr, was die Waldgeister auf der Windwärtsinsel mehr mögen als alles andere auf der Welt?\n\nGenau, Schuhe!\n\nUnd wir werden sie ihnen stehlen. Das wird sie ganz verrückt machen! Ha!\n\nAber leider fürchte ich mich vor Waldgeistern, also werdet Ihr das erledigen müssen, {name}.", sourceObjective = "Stehlt 14 gestohlene Stiefel zurück.", progress = "Und? Wie hat ihnen das geschmeckt? Sind sie ausgeflippt?", completion = "Wie ich sehe, habt Ihr und Ningna Euch einen kleinen Scherz erlaubt. Leider kann der Orden ein solches Verhalten nicht gutheiß... \n\nMoment, wo habt Ihr diese Schuhe gefunden? Ich habe schon seit Ewigkeiten nach diesem Paar Reitstiefel aus Maulwurfsfell gesucht!\n\nNun gut... Dieses eine Mal werde ich ein Auge zudrücken. Hmpf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31701] = { id = 31701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Jägerin", description = "Ich habe erfahren, dass eine bösartige Bestie, eine Windwärtsjägerin, den Wald im Nordwesten der Insel terrorisiert.\n\nSie hat bereits mehrere Schlangen getötet und nicht wenige Schlangenreiter verletzt, die ihrem Treiben Einhalt gebieten sollten.\n\nSie muss aus dem Weg geräumt werden, bevor sie noch größeren Schaden anrichten kann. Könntet Ihr diese Aufgabe übernehmen?", sourceObjective = "Tötet die Windwärtsjägerin.", completion = "Vielen Dank, {name}. Ihr erweist Euch als äußerst verlässlicher Schüler.", sourceObjectiveStatus = "unverified-source-field" }
quests[31702] = { id = 31702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdbefehl", description = "Ich habe von einer großen weißen Bestie erfahren, die sich in dem Wald im Nordwesten der Insel, auf der die wilden Schlangen leben, herumtreibt.\n\nDiese wilde Kreatur ist der Gefährte der Windwärtsjägerin und hat bereits mehrere der ausgewachsenen Wolkenschlangenmatriarchinnen zu Fall gebracht.\n\nWir können nicht zulassen, dass solch ein gefährliches Raubtier die Insel unsicher machen darf.\n\nNehmt Euch dieser Kreatur an. Wir werden sehen, ob sich Eure Ausbildung ausgezahlt hat.", sourceObjective = "Tötet den Windwärtssäbler.", completion = "Wie ich sehe, habt Ihr die Bestie bezwungen. Ihr seid wirklich ein vielversprechender Schüler.", sourceObjectiveStatus = "unverified-source-field" }
quests[31703] = { id = 31703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab mit dem Tollkopf", description = "Es gibt eine weitere Aufgabe, mit der ich Euch beauftragen muss.\n\nDer Anführer der Waldgeister ist der Schattenfeetollkopf.\n\nWenn es irgendwo Ärger gibt, ist er meist derjenige, der im Hintergrund die Fäden zieht.\n\nWir haben keine Zeit, um uns mit den ermüdenden Possen und Frechheiten der Waldgeister herumzuschlagen. Nehmt den Schattenfeetollkopf aus dem Spiel... und tut es schnell.", sourceObjective = "Tötet den Schattenfeetollkopf.", completion = "Den wären wir los! Bei all den Problemen, mit denen wir uns momentan herumschlagen müssen, ist es gut zu wissen, dass sich zumindest eines davon gerade gelöst hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[31704] = { id = 31704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Häufchen gemacht", description = "<Als Ihr Eure Schlange anblickt, senkt sie verschämt den Kopf.>\n\nEuch wird klar, dass jemand aus seinem Pferch ausgebüxt ist und einen kleinen \"Unfall\" gehabt hat.\n\nNun ja, bei solch einem Hunger war abzusehen, dass es irgendwann am anderen Ende wieder herauskommen musste.\n\nIhr solltet lieber die Häufchen Eurer Schlange finden und aufsammeln, bevor die Schlangenmeister davon erfahren.", sourceObjective = "Sammelt 5 kleine Beutel mit Häufchen.", progress = "<Das Jungtier blickt Euch unschuldig an.>", completion = "Das Jungtier spielt zufrieden vor sich hin und ist sich Eurer Anstrengungen gar nicht bewusst. Manchmal ist das Leben eines Schlangenausbilders wirklich undankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31705] = { id = 31705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angst vor der Nadel", description = "Das Arboretum ist unser Zuhause, ein sicherer Hafen, in dem wir unsere Jungtiere aufziehen und unsere Schüler ausbilden.\n\nLeider gibt es aber auch andere, gefährlichere Kreaturen, die es ebenfalls gern ihr Zuhause nennen würden.\n\nHinter dem Fluss im Norden haben wir eine gewaltige Wespe entdeckt, die sich von den dortigen Nektarblüten ernährt.\n\nDiese Kreatur hat bereits mehrere unserer Schüler gestochen.\n\nBenutzt den Honig hier, um die Wespe aus ihrem Versteck zu locken. Dann beseitigt sie, bevor sie noch jemandem Leid zufügen kann.", sourceObjective = "Benutzt den Honig auf der nördlichen Lichtung im Arboretum und tötet dann den Obstgartennadler.", completion = "Die Giftwespe ist tot? Gut. Wo andere Schüler versagt haben, habt Ihr obsiegt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31706] = { id = 31706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weinende Witwen", description = "Die Spinnen in der Umgebung von Sri-La sind in jüngster Zeit sehr aggressiv geworden. Sie stellen ein signifikantes Problem für die Angler dar, die entlang der Küste fischen.\n\nUm ihre Sicherheit zu gewährleisten, müsst Ihr Euch in das Klagen der Witwe begeben und dort die weinenden Witwen eliminieren.\n\nIhr könnt die Höhle an der Küste im Norden finden.", sourceObjective = "Tötet 7 weinende Witwen.", completion = "Ausbilder Himmelsdorn hat mich über die Situation am Klagen der Witwe auf dem Laufenden gehalten. Ihr habt das gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31707] = { id = 31707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verheddert", description = "Wir haben einen beunruhigenden Bericht von den Anglern in Sri-La erhalten, {name}.\n\nViele ihrer Dorfbewohner werden vermisst - wahrscheinlich wurden sie von den Spinnen entführt, die in der als Klagen der Witwe bekannten Höhle an der Nordküste leben.\n\nDie Opfer werden in die dunklen Tiefen verschleppt, eingesponnen und so als nächste Mahlzeit aufbewahrt.\n\nWir glauben, dass einige von ihnen noch am Leben sein könnten. Es bleibt immer noch Zeit, sie zu retten! Geht und rettet so viele Dorfbewohner, wie ihr könnt.", sourceObjective = "Zerstört die Witwennetze, um 5 Dorfbewohner von Sri-La zu befreien.", completion = "Ihr habt heute Großes geleistet, {name}. Das ist es, was den Orden der Wolkenschlange ausmacht - die Bewohner des Jadewalds zu beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31708] = { id = 31708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenschuppe", description = "Wie ich sehe, habt ihr nun ein eigenes Jungtier, {race}.\n\nHabt ihr es auch gut gefüttert, für seine Sauberkeit gesorgt und mit ihm gespielt? Nur dadurch wird es stark und gesund werden.\n\nLasst mich Euch ein kleines Trainergeheimnis verraten. Im Klagen der Witwe im Norden lässt sich ein Pilz namens Schlangenschuppe finden.\n\nEr ist relativ schwer zu beschaffen, aber dieser Pilz verfügt über mächtige Eigenschaften und wichtige Nährstoffe. Eure Schlange wird ihn nicht gerade mögen, aber wer isst schon gern sein Gemüse auf?", sourceObjective = "Sammelt 25 Schlangenschuppen.", progress = "<Eure Schlange begrüßt Euch freudig.>", completion = "<Eure Schlange schnuppert an den Pilzen und verzieht das Gesicht. Sie versucht zu entkommen, aber ihr haltet sie sanft fest und bringt sie dazu, die schwammigen Happen zu fressen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31709] = { id = 31709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagender Zweifel", description = "Mir ist zu Ohren gekommen, dass es einige merkwürdige Vorkommnisse am Klagen der Witwe im Norden gab.\n\nHyazinthe und ich haben uns aufgemacht, um die Sache zu untersuchen, und ich bin mir sicher, dass irgendeine Manifestation des Sha seinen Weg in die Höhle gefunden hat.\n\nIch habe dieses Gerät konstruiert, um Sha-Energie zu messen.\n\nFalls Ihr dorthin unterwegs seid, könntet Ihr dann Messungen an allen Orten mit Sha-Befall vornehmen?\n\nDer Befall stellt sich meist als schwarz-weißer Strom aus Sha-Energie dar, der aus dem Boden hervorbricht.", sourceObjective = "Benutzt das Sha-Abstimmungsgerät an Orten mit Sha-Befall im Klagen der Witwe. Der Eingang zum Klagen der Witwe kann an der Küste im Norden gefunden werden, südlich von Sri-La.", completion = "Vielen Dank, dass Ihr mir diesen Bericht gebracht habt, {name}. Bao der Große ist zu Recht beunruhigt.\n\nDas Sha ist ein perfider und tödlicher Gegner. Wir müssen es uns zum Ziel setzen, seine dunkle Energie von diesem Land zu tilgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31710] = { id = 31710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckerlis", description = "Als Ihr Euch nähert, öffnet Eure Schlange ihr Maul und fängt an zu sabbern. Sieht aus, als hätte sie ganz schönen Hunger bekommen, seit Ihr sie das letzte Mal gesehen habt.\n\nDer Art und Weise nach, wie sie wimmert und mit dem Schwanz um sich schlägt, sieht es so aus, als würde irgendein beliebiges Leckerli wohl nicht mehr ausreichen - ein ganz besonders spezieller Leckerbissen muss her.\n\nEure Schlange liebt es, auf winzigen Spinnenaugen herumzukauen, aber diese Spezialität findet man nur bei den Witwenbrutspinnen in der Höhle an der Nordküste.\n\nTja, was soll ein Reiter machen? Eure Schlange wartet.", sourceObjective = "Sammelt 100 winzige Spinnenaugen.", progress = "Eure Schlange richtet sich auf, als Ihr zurückkehrt.", completion = "Eure Schlange gibt Euch einen liebevollen Stups, bevor sie die Leckerlis verschlingt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31711] = { id = 31711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saat des Zweifels", description = "Das Problem mit dem Sha des Zweifels ist seine tiefdringende Hinterlist, {race}.\n\nSobald die Saat des Zweifels gesät ist, wächst sie wie ein lästiges Unkraut.\n\nEine solche Saat wurde im Klagen der Witwe nördlich von hier gesät und genau wie ein Unkraut müssen wir sie so schnell wie möglich beseitigen.\n\nIhr müsst das nagende Fragment des Zweifels zerstören, bevor es weitere Opfer befallen kann.", sourceObjective = "Tötet die Saat des Zweifels.", completion = "Ausgezeichnete Arbeit, {name}. Ich \"bezweifle\" allerdings, dass dieser Feind für immer besiegt ist. Wir müssen wachsam bleiben, bis wir uns dessen sicher sein können.", sourceObjectiveStatus = "unverified-source-field" }
quests[31712] = { id = 31712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affenärger", description = "Uns wurden merkwürdige Nachrichten aus Sri-La zugetragen.\n\nAnscheinend hat es sich ein Ho-zen-Stamm in Uuna Kagu gemütlich gemacht, einer Höhle an der Küste südlich des Fischerdorfs.\n\nEin bisschen zu gemütlich, wenn Ihr mich fragt. Ihre Stammesangehörigen stehlen und plündern die Rohstoffe entlang der gesamten Küste.\n\nWir müssen ihnen eine Lektion erteilen... eine Lektion, die nur mit Härte erreicht werden kann. Sie sind schon zu lang kein gern gesehener Gast mehr.", sourceObjective = "Tötet 13 Uuna-Ho-zen.", completion = "Die Anwesenheit der Ho-zen ist beunruhigend. Ihr habt gut daran getan, die Anweisungen von Ausbilder Himmelsdorn zu befolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31713] = { id = 31713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uuna-hört", description = "Das ist eine Katastrophe, {name}!\n\nAls ich gestern die Gaststätte \"Die Tanzende Schlange\" besucht habe, war ihnen das Bräu ausgegangen. Sie haben gesagt, jemand hätte die Lieferung aus Sri-La gestohlen. GESTOHLEN!\n\nDiese Ho-zen von Uuna haben anscheinend jede Menge Ärger unten an den Docks gemacht, und sie haben all das Bräu in ihre Höhle in Uuna Kagu an der Küste verschleppt.\n\nMit so einer Trockenperiode kann ich nicht leben. Ein Leben ohne Bräu ist nicht lebenswert!\n\nJemand muss hingehen und das Bräu retten!", sourceObjective = "Sammelt 100 Sri-La-Starkbier.", progress = "Ist das Bräu schon zurück? Ich... ich halte das nicht mehr lange aus...", completion = "Oh, den Sturmbräus sei Dank! Ihr seid ein wahrer Held", sourceObjectiveStatus = "unverified-source-field" }
quests[31714] = { id = 31714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlangen retten", description = "Diese Uuna-Ho-zen sind diesmal eindeutig zu weit gegangen.\n\nWisst Ihr, was sie mit den wilden Wolkenschlangen anstellen? Jungtiere, die sie gefangen haben, müssen in ihren Gruben gegeneinander kämpfen - und das nur zum Vergnügen der Uuna!\n\nBarbaren!\n\nWenn die Jungtiere bereits in diesem Alter solch aggressives Verhalten beigebracht bekommen, werden sie gewalttätig und verderbt, sobald sie ausgewachsen sind. Eine bösartige Wolkenschlange ist nichts, womit wir zu tun bekommen wollen.\n\nWir müssen die Jungtiere retten.", sourceObjective = "Sammelt 10 gerettete Schlangen.", progress = "Der Orden der Wolkenschlange hat über Jahrhunderte hinweg darauf hingearbeitet, aus wilden Wolkenschlangen treue Gefährten zu machen. Unsere Güte bringt das Beste in ihnen zum Vorschein.\n\nUnglücklicherweise können Gewalt und Zorn sie sehr schnell in zerstörerische Monster verwandeln.", completion = "Ah, ja - diese Jungtiere sehen in der Tat müde aus. Sie haben Schlimmes durchgestanden, aber dank Euch sind sie jetzt in Sicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[31715] = { id = 31715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uuna-bittlich", description = "Der Anführer der Ho-zen von Uuna ist ein Brigant namens Fürst Uuna.\n\nIch habe fürchterlichte Geschichten über diesen marodierenden Kapitän und seine Mannschaft gehört. Wo auch immer er mit seinem Stamm aufkreuzt, folgt Zerstörung auf dem Fuße.\n\nDie Uuna landen mit ihren Booten auf fruchtbarem Boden, brandschatzen die Dörfer in der Nähe und lassen das Land leerbluten, bevor sie sich zu ihrer nächsten Eroberung aufmachen.\n\nWir werden nicht zulassen, dass das an unserer Küste passiert, nicht, während ich noch das Sagen habe.\n\nJemand muss gehen und ihn sofort auslöschen.", sourceObjective = "Tötet Fürst Uuna.", completion = "Ihr Anführer ist also tot? Gut. Vielleicht lassen die Ho-zen die Dorfbewohner jetzt in Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31716] = { id = 31716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Häufchen gemacht", description = "<Als Ihr auf den Pferch zuschreitet, huscht die Schlange in eine der Ecken und versteckt sich.>\n\nSo, wie sie Euch mit verschämten Augen ansieht, wird Euch klar, dass jemand aus seinem Pferch ausgebüxt ist und einen kleinen... Unfall gehabt hat.\n\nNun ja, bei solch einem Hunger war abzusehen, dass es irgendwann am anderen Ende wieder herauskommen musste.\n\nIhr solltet lieber die Häufchen Eurer Schlange finden und aufsammeln, bevor die Schlangenmeister davon erfahren.", sourceObjective = "Sammelt 5 große Beutel mit Häufchen.", progress = "<Die Schlange sieht Euch amüsiert zu.>", completion = "Die Wolkenschlange spielt zufrieden vor sich hin und ist sich Eurer Anstrengungen gar nicht bewusst. Seufz… Manchmal ist das Leben eines Schlangenausbilders wirklich undankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31717] = { id = 31717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Trainers: Flitze Langpranke", description = "Ihr steigt in der Rangfolge unserer Schüler auf, {name}.\n\nSo wie ein Schwert im Feuer geschmiedet werden muss, müssen sich unsere Schüler gegeneinander beweisen.\n\nHeute kämpft Ihr gegen einen unserer klügsten Schüler, Flitze Langpranke. Um ihn zu besiegen, müsst Ihr auf Eure Verteidigungskünste zurückgreifen.\n\nSprecht ihn im Trainingsring an, um mit der Herausforderung zu beginnen. Viel Glück.", sourceObjective = "Sprecht mit Flitze Langpranke und besiegt ihn.", completion = "Gut gemacht, {class}. Das Schwert das gehämmert und gefaltet wird erhält eine scharfe Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[31718] = { id = 31718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Trainers: Bao der Große", description = "Seid Ihr bereit für eine weitere Lektion, {name}?\n\nHeute werdet Ihr mit Bao dem Großen trainieren. Er hat einen großen Körper, aber auch ein großes Herz und er wird nicht aufgeben, bevor er nicht vollständig besiegt ist.\n\nFalls Ihr ihn besiegen wollt, werdet Ihr Durchhaltevermögen beweisen müssen.\n\nSprecht ihn im Trainingsring an, um die Herausforderung anzunehmen. Viel Glück.", sourceObjective = "Sprecht mit Bao dem Großen und besiegt ihn.", completion = "Ihr habt beide bis zum Ende durchgehalten. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31719] = { id = 31719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Trainers: Ningna Dunkelrad", description = "Ihr seid vielversprechend, {name}. Talent ohne Disziplin und Demut ist jedoch nichts wert.\n\nHeute werdet Ihr Ningna Dunkelrad gegenübertreten. Ihre angeborene Stärke macht sie zu einer unserer talentiertesten Schülerinnen.\n\nWenn Ihr sie besiegen wollt, müsst Ihr höchste Selbstkontrolle beweisen.\n\nSprecht sie im Trainingsring an, um mit der Herausforderung zu beginnen. Viel Glück.", sourceObjective = "Sprecht mit Ningna Dunkelrad und besiegt sie.", completion = "Ein Kampf gegen Ningna zeigt die eigenen Stärken und Schwächen ganz genau. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31720] = { id = 31720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Trainers: Suchi die Süße", description = "Heute steht Ihr Suchi der Süßen im Ring gegenüber. Trotz ihres süßen Aussehens ist sie ein harter Gegner.\n\nSie greift schnell und mit sicherer Hand an, aber mit der Zeit können solch starke Angriffe ermüden.\n\nWenn Ihr sie besiegen wollt, müsst Ihr Euren Schaden auf die Momente konzentrieren, in denen sie geschwächt ist.\n\nSprecht mit Suchi, um mit dem Duell anzufangen. Viel Glück.", sourceObjective = "Sprecht mit Suchi der Süßen und besiegt sie.", completion = "Eure Konzentration ist exzellent, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[31721] = { id = 31721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Trainers: Qua-Ro Weißstirn", description = "Qua-Ro Weißstirn gilt als einer der besten Schüler des Ordens.\n\nEr scheint keine Schwachstelle zu haben. Er ist von regem Geist und starkem Arm, arbeitet hart und ist talentiert.\n\nWenn Ihr ihm im Ring gegenübersteht, werdet Ihr Euch an unserem Besten messen.\n\nSprecht mit ihm, um das Duell zu starten. Was immer das Ergebnis sein wird, ihr werdet viel daraus lernen, ihn herauszufordern.", sourceObjective = "Sprecht mit Qua-Ro Weißstirn und besiegt ihn.", completion = "Euer Können ist erstaunlich, {name}. Wenn ich so vielversprechende Schüler wie Euch sehe, weiß ich, dass der Orden in gute Hände kommen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[31723] = { id = 31723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal der Vier Winde", description = "Yarr, der Jadewald wird gerade mit Hochdruck umgebaut, aber das Tal der Vier Winde ist reif zum Entdecken. Ich kann Euch hinbringen, wenn Ihr es erkunden wollt. Seht Euch meine Waren an, wenn Ihr Ausrüstung braucht, die Euch auf Eurer Reise hilft.", sourceObjective = "Sprecht mit dem Gefreiten Tim P. Orär im Tal der Vier Winde.", sourceObjectiveStatus = "unverified-source-field" }
quests[31724] = { id = 31724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mac Donald", description = "Einzig und allein anzufangen demonstriert, wie zäh Ihr seid!\n\nMac Donald hat mir alles beigebracht, was ich über das Kämpfen weiß. Ich glaube, ein Kampf gegen ihn wäre eine großartige Lernerfahrung für Euch!\n\nIhr findet ihn direkt auf der anderen Seite der Brücke nach Westfall. Lasst Euch von seinem Alter nicht täuschen, er hat bereits einige aufstrebende Nachwuchslehrer wie Euch geschlagen.", sourceObjective = "Besiegt Mac Donald in einem Haustierkampf.", completion = "Tja, gegen diese Ergebnisse kann man nichts einwenden. Ihr habt eine echte Gabe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31725] = { id = 31725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lindsay", description = "Wollt Ihr zeigen, was Ihr drauf habt? Im Rotkammgebirge oben gibt es ein kleines Mädchen, das in der Kampfszene Furore gemacht hat.\n\nFindet Lindsay beim Dock im Immerruhlager. Sie ist zwar jung, aber über ihre beeindruckenden Leistungen müsst Ihr Euch nicht lustig machen!", sourceObjective = "Besiegt Lindsay in einem Haustierkampf.", completion = "Ihr seid gemein! Warum hat Ihr mich nicht gewinnen lassen? Die anderen lassen mich immer gewinnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31726] = { id = 31726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eric Davidson", description = "All meine Freunde reden von einem Furcht einflößenden Worgen namens Eric Davidson im Dämmerwald, den niemand mit seinen Haustieren zu bekämpfen wagt.\n\nWenn Ihr ihn findet und bezwingt, möchte ich wetten, dass nicht mehr sein Name, sondern vielmehr Eurer in aller Munde sein wird!", sourceObjective = "Besiegt Eric Davidson in einem Haustierkampf.", progress = "Habt Ihr etwa Angst, {race}?", completion = "Nicht nur habt Ihr weder mich noch meine Heimat gefürchtet, Ihr habt mich ehrenhaft besiegt. Ich bin beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31727] = { id = 31727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riskantes Spiel", description = "Wenn wir diesen Krieg gewinnen wollen, dürfen wir nichts aus den Augen verlieren, <Fremder/Fremde>.\n\nAn der Küste gibt es Störungen, die untersucht werden müssen. Was immer dort anwesend ist gehört nicht zu uns und ist für uns wertlos. Die Vorräte dort könnten sich jedoch als sehr wertvoll erweisen.\n\nWenn es dort etwas Nützliches gibt, müssen wir es vor der Kaiserin erreichen.", sourceObjective = "Sprecht in der Schreckensöde mit Deckoffizierin Arie bei Tropfs Wagnis.", completion = "Die Käfer haben also Interesse an uns entwickelt, was? Nun, wenn sie etwas von uns wollen, müssen sie schon herkommen und es sich verdienen!\n\nHier erarbeitet man sich alles, was man bekommt. Das gilt auch für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[31728] = { id = 31728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bill Schildbuckel", description = "Mein langjähriger Freund, Trainerkollege und berüchtigter Trunkenbold Bill Schildbuckel vom Schlingendornkap hat eine allen hinreichend vorbereiteten Trainern offen stehende Herausforderung proklamiert!\n\nIhr solltet seinem Aufruf folgen und Eure Fertigkeiten auf die Probe stellen. Er wandert häufig auf den Straßen des südlichen Kaps umher.", sourceObjective = "Besiegt Bill den Piraten in einem Haustierkampf.", completion = "Ich verlange eine Wiederholung... hick! Dasch war unfair! Ihr hattet Euren Zwilling dabei!", sourceObjectiveStatus = "unverified-source-field" }
quests[31729] = { id = 31729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steven Lisbane", description = "Wenn Ihr findet, dass ich zäh war, wappnet Euch lieber. Ab hier wird es noch schwieriger.\n\nFindet Steven Lisbane, der die Straßen im Südteil des Nördlichen Schlingendornentals durchstreift. Sucht ihn und findet heraus, wer hier der bessere Zähmer ist!", sourceObjective = "Besiegt Steven Lisbane in einem Haustierkampf.", completion = "Was für eine Vorstellung! Ein wahrlich vortreffliches Scharmützel.", sourceObjectiveStatus = "unverified-source-field" }
quests[31730] = { id = 31730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig freundlicher Auftrag", description = "Späher haben von der Anwesenheit von Nichtmantis bei Kor'vess berichtet. Ihr Eindringen und ihre Berndiebstähle würden normalerweise schnell unterbunden werden, aber unsere Truppen werden anderswo gebraucht.\n\nDiese Aufgabe scheint zu Euch zu passen, <Erwecker/Erweckerin>. Ihr werdet sie dazu bringen, dieses Land zu verlassen, oder Ihr werdet sie im Namen der Klaxxi'va vernichten.", sourceObjective = "Sprecht im Braugarten in der Schreckensöde mit Saftmeister Vu.", completion = "Sie wollen also, dass wir gehen, was? Wie selbstsüchtig von ihnen! Wir nehmen uns nur von einem Baum Bern.\n\nIch gehe jedenfalls nirgendwohin! Ich habe zu brauen.\n\nWenn Ihr uns helft, können wir vielleicht zu einer Übereinkunft gelangen, die beiden Seiten hilft. Ich gebe ihnen etwas Bräu, und sie hören auf zu versuchen, uns umzubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31732] = { id = 31732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hölle entfesseln", description = "Ich werde NICHT zulassen, dass die Horde vor uns in diesen Gefilden Fuß fasst! Wenn Ihr Euch ins Gefecht stürzen wollt, nehmt den Gyrokopter am Ende der Startbahn. Ein Angriffsvektor ist bereits einprogrammiert, also könnt Ihr Euch auf die Rolle des Bordschützen konzentrieren.\n\nSorgt dafür, dass über diesen Orcs die Hölle losbricht!", sourceObjective = "Benutzt einen Himmelsfeuer-Gyrokopter, um 60 Soldaten der Garrosh'ar zu töten, 8 Schredder der Garrosh'ar zu zerstören und anschließend die Klingenfaustschneide und die Höllennarbe zu versenken.", progress = "Worauf wartet Ihr denn?! Steckt den Boden unter ihnen in Brand!", completion = "Ein angemessener Empfang für die Horde in diesem neuen Land!", sourceObjectiveStatus = "unverified-source-field" }
quests[31733] = { id = 31733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichere Landung", description = "Ihre Stadt brennt und ihre Männer sind versprengt und gebrochen. Ich brauche JETZT alle verfügbaren Männer vor Ort, um sie zu erledigen.\n\nGreift Euch einen der Fallschirme am Rand des Schiffes und runter mit Euch!", sourceObjective = "Springt mit einem Fallschirm der Himmelsfeuer über Garrosh'ar ab und sprecht mit Sully \"der Gurke\" McLeary.", completion = "War Zeit, dass Ihr auftaucht, Kumpel! Richten wir etwas Schaden an!", sourceObjectiveStatus = "unverified-source-field" }
quests[31734] = { id = 31734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böllerwagen", description = "Habt Ihr gesehen, wie groß diese Kriegswagen sind? Sie transportieren so viel Sprengstoff, dass ich nicht weiß, ob die Horde hier ist, um diesen Kontinent zu erobern oder ihn einfach nur ins Meer hinauszujagen!\n\nWir müssen die Wagen unschädlich machen, ehe sie Garrosh'ar verlassen.\n\nHier, nehmt meine Taschenleuchtfeuer. Schießt damit auf einen Wagen und genießt das Feuerwerk!", sourceObjective = "Zerstört mit Sullys Leuchtpistole 5 Kriegswagen der Horde.", progress = "Schickt Euch \"Die Gurke\" mit einer Mission?", completion = "Da die Wagen nun unbrauchbar sind, können wir unsere Aufmerksamkeit dem Kommandanten zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[31735] = { id = 31735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Werkzeug zur Hand", description = "Ich habe die Umgebung abgesucht und keine Spur vom Prinzen oder von Admiral Taylor gefunden. Wir müssen diese Basis schnell neutralisieren und unsere Suche anderswo fortsetzen.\n\nDie Einsätze hier werden von Ga'trul, einem Hexenmeister der Orcs, geleitet. Er hat das Dock verbarrikadiert und versucht, durch einen dämonischen Zirkel zu entkommen.\n\nSetzt diese Leuchtpistole wieder ein und jagt die Barrikaden in die Luft! Ich werde Euch den Rücken freihalten und vorrücken, wenn Ihr Ga'trul erreicht.", sourceObjective = "Räumt mit Sullys Leuchtpistole die Barrikaden und konfrontiert Ga'trul am Ende des Docks.", progress = "Wir werden unsere Mission abschließen, doch jetzt ist dieser Hexenmeister unsere oberste Priorität!", completion = "Wir werden ihn wieder einholen. Da bin ich ganz sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[31736] = { id = 31736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesandter der Allianz", description = "Nördlich dieser Basis gibt es einen Kirschblütenhain, hinter dem sich ein Dörfchen versteckt. Dort wollen wir unser Lager aufschlagen und uns um unsere Verletzten kümmern, während wir unseren nächsten Schachzug planen.\n\nMacht Euch ins Dorf auf und nehmt Kontakt mit dem Anführer der Eingeborenen auf. Agentin Mishka und ich werden dort zu Euch stoßen.\n\nUnd seid höflich, {name}! Ich autorisiere Euch hiermit, die gesamte Allianz vor Ort zu vertreten.\n\nIch zähle darauf, dass der Anblick eines Allianzhelden von Eurem Format etwas Eindruck schinden wird.", sourceObjective = "Spürt den Anführer von Pel'zin auf und trefft Euch mit ihm.", completion = "Als sich die Nebel senkten, wussten wir, dass es nur eine Frage der Zeit war, bis sich Besuch einstellt.\n\nDass es zu so etwas kommen würde, hätten wir nicht vorausahnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[31737] = { id = 31737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis des Krieges", description = "Der ganze Ort geht in Flammen auf und die Himmelsfeuer meldet, dass weitere von diesen... Schatten aus dem Erdboden hervorkriechen. Wir müssen unsere Leute da herausholen.\n\nRäumt auf Eurem Weg nach Norden einen Pfad durch die Basis und nehmt Kurs auf die Stadt. Ich werde dort zu Euch stoßen.", sourceObjective = "Tötet 10 Sha-Heimsuchungen und 5 Sha-Herolde bei Garrosh'ar.", completion = "Ich bin froh, dass Ihr die Verantwortung für Eure Taten übernommen habt. Wenn ihnen nicht Einhalt geboten wird, können negative Emotionen einen Einzelnen sehr schnell überwältigen – so, wie es demjenigen, den Ihr \"Rell\" nennt, widerfahren ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[31738] = { id = 31738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plündernde Peons", description = "Wie ist aus meinem Dorf nur ein Schlachtfeld geworden?\n\nIm Westen haben Eure Feinde von der Horde unseren kostbaren Obstgarten niedergemäht. Ohne unsere Apfelbäume gibt es keine Ernte, keine Nahrung und keinen Lebensunterhalt.\n\nWenn Ihr wirklich anders seid als die Horde, beweist es uns! Helft uns, unseren Hain zu beschützen, und tötet diejenigen, die das Land schänden.", sourceObjective = "Tötet 12 Vorarbeiter oder Peons von Zwillingsfels.", completion = "Unser Obstgarten ist einer der größten Schätze des Dorfes. Wir sind Euch wirklich dankbar, dass Ihr unsere Ernte gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31739] = { id = 31739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prioritäten!", description = "Diese \"Orcs\" haben die Brauerei geplündert und sich mit Fässern unseres besten Apfelweins davongemacht!\n\nIch weiß, dass da draußen ein Krieg tobt, aber ich bin nicht die Sorte Braumeister, die untätig zusieht, wie sein bester Jahrgang gestohlen wird, damit er den Durst Unwürdiger löscht.\n\nDiese \"Horde\" wird das mit Sicherheit nicht tatenlos über sich ergehen lassen. Warum macht Ihr Euch mit Eurer Waffe nicht nützlich und helft mir, meinen Apfelwein zurückzuholen?", sourceObjective = "Sammelt 6 Fässer Apfelblütenwein.", progress = "Ist das da bei Euch etwa mein Mann? Konntet Ihr den Apfelblütenwein bergen?", completion = "Wie ich sehe, wart Ihr fleißig! Danke, dass Ihr unsere Fässer zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31740] = { id = 31740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaukaus Randale", description = "Wir haben mehr Sorgen als nur unsere Kellerei.\n\nKaukau, unser geliebtes Mushan, ist verrückt geworden! Schaut ihn Euch nur an!\n\nIch habe alles versucht: locken und bitten, schreien und beruhigen. Nichts hat geholfen.\n\nEr hat den Verstand verloren. Es gibt nur einen Weg, ihn und unsere Brauerei zu retten.\n\nMacht kurzen Prozess. Er wird nichts spüren.", sourceObjective = "Tötet Kaukau.", completion = "Ihr habt gut daran getan, den Brauern zu helfen und mir von den Ereignissen zu berichten.\n\nNach dem, was Ihr mir erzählt habt, befürchte ich, dass Kaukau von dunkler Energie besessen war. Könnte es etwa...?\n\nNein. Das wäre unmöglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[31741] = { id = 31741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burg Zwillingsfels", description = "Ich traue dieser Horde nicht. Sie wirken üble Magie und ihre Absichten sind offensichtlich bösartiger Natur. Burg Zwillingsfels steht direkt vor den Toren Pel'zins – wir können ihre Präsenz dort nicht mehr hinnehmen.\n\nIch bitte Euch, <Fremder/Fremde>: Dezimiert ihre Truppen, bevor sie etwas Schreckliches mit unserem Dorf anstellen!", sourceObjective = "Tötet 15 Gefolgsleute der Horde in der Burg Zwillingsfels.", completion = "Ihr habt dort unten ja ein ziemliches Chaos angerichtet, Kleiner.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[31742] = { id = 31742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmentierte Fraktion", description = "Die Horde hat uns die Arbeit erleichtert. Ihre Flügelkämpfe und die Fragmentierung ihrer eigenen Reihen hat ihr Lager in zwei Parteien gespalten: die Orcs im Westen und die Untoten im Osten.\n\nDie Orcs gehorchen den Befehlen ihres Kommandanten Dalgan, während die Untoten Bellandra Teufelssturm, einer mächtigen Hexenmeisterin, folgen. Hoffentlich ist dieses interne Gerangel Ablenkung genug, damit Ihr Euch einschleichen und beide töten könnt. Sully hat die Ruinen bereits infiltriert – meldet Euch bei ihm, wenn Ihr fertig seid.", sourceObjective = "Tötet Dalgan und Bellandra Teufelssturm.", progress = "Ganz schön beängstigende Gestalten sieht man hier...", completion = "So was nenn' ich töten mit Stil, {class}.\n\nJetzt, wo die beiden erledigt sind, muss nur noch der Riesenkerl dort hinter mir in der Halle dran glauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[31743] = { id = 31743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor Feuer kommt Rauch", description = "Sully hat die Einrichtung der Horde im Norden ausgekundschaftet und berichtet, einen großen Haufen Sprengstoff und ein kleines Kontingent Demolierer gesehen zu haben – von den Dämonen, die von ihren Hexenmeistern beschworen worden sind, ganz zu schweigen.\n\nZum Glück sind wir vorbereitet. Wir haben Unterstützung von der Himmelsfeuer. Wir müssen unseren Piloten nur zeigen, wo sie zuschlagen sollen.\n\n<Mit einem wissenden Nicken drückt Euch Rell ein Rauchsignal in die Hand.>", sourceObjective = "Fordert mit dem Rauchsignal der Allianz einen Luftangriff auf den Munitionshaufen, die Demolierer von Zwillingsfels, die Wildwichtel und Xhu'daggab an.", completion = "Meine Burschen im Himmel oben heizen ordentlich ein, stimmt's? Ha ha ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[31744] = { id = 31744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfairer Handel", description = "Wir sind uns zwar gerade erst begegnet, doch wir haben einen gemeinsamen Feind: die Gruppierung, die die \"Horde\" genannt wird.\n\nVor ein paar Tagen hat uns ihr Anführer einen Handel vorgeschlagen. Als wir ablehnten, haben seine Diener mehrere unserer Kinder als Druckmittel entführt.\n\nWir haben zwar versucht, die Shado-Pan herbeizurufen, um zu helfen, aber sie befinden sich am Kun-Lai-Gipfel, mehrere Tagesreisen von hier entfernt. Könnt Ihr uns womöglich helfen?", sourceObjective = "Befreit 8 gefangene Pandarenkinder aus der Burg Zwillingsfels, indem Ihr die dämonischen Augen tötet, von denen sie bewacht werden.", completion = "Ja, ich hab die Kleinen auch gesehen. Hab auf dem Weg hierher ein paar von ihnen in Sicherheit gebracht.\n\nGute Arbeit, Kleiner. Die Kinners werden vielleicht ein paar üble Alpträume haben, Euch verdanken sie aber, dass sie eine Zukunft haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[31745] = { id = 31745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts ins Landesinnere", description = "\"Sha\"-Energie also, hm? Seid vorsichtig, {name} – irgendetwas Dunkles verbirgt sich auf diesem Kontinent.\n\nWir bleiben zurück, um mit dem Rest der Horde fertigzuwerden, aber Ihr müsst mit der eigentlichen Mission fortfahren: der Rettung von Kapitän Taylor und der Suche nach Prinz Anduin.\n\nUnsere Luftaufklärer haben etwas nahe des Dorfs Pel'zin gesichtet, das das Wrack des Flaggschiffs sein muss. Begebt Euch dorthin und meldet Euch bei Admiralin Rogers für weitere Instruktionen.\n\nUnd ja, Ihr dürft meinen Gyrokopter benutzen.", sourceObjective = "Erstattet Himmelsadmiralin Rogers in Pel'zin im Jadewald Bericht.", completion = "Ausgezeichnete Arbeit, {class}. Jetzt verstehe ich, warum Ihr so nachdrücklich empfohlen wurdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[31752] = { id = 31752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 4000", sourceObjective = "Es freut mich sehr, Euch dieses Geschenk überreichen zu dürfen, {race}. Laut meinen Berechnungen sollte es Gefühle der Freude und Dankbarkeit hervorrufen.\n\nEinen schönen Tag noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31754] = { id = 31754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenfeuer", description = "Diese Mogukanonen oben auf der Goldenen Treppe bombardieren uns aus der Distanz. Wäre nicht schlecht, wenn die irgendwie ganz spontan kaputtgehen würden, nicht wahr?", sourceObjective = "Zerstört 7 Kanonen der Shao-Tien.", sourceObjectiveStatus = "unverified-source-field" }
quests[31755] = { id = 31755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausamkeiten", description = "Ich kann die Schreie der gefangenen Soldaten und Dorfbewohner oben auf der Goldenen Treppe hören. Sie werden gefoltert!\n\nBitte, bitte, Ihr müsst sie retten!", sourceObjective = "Rettet 5 Wachposten des Goldenen Lotus oder Dorfbewohner von Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[31756] = { id = 31756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohe Regenwahrscheinlichkeit", description = "Die Mogu beschwören auf der Goldenen Treppe irgendeine Art finsteren Sturm. Im Allgemeinen sind Mogu und Blitze keine besonders angenehme Mischung. Ich würde sagen, wir halten sie auf.\n\nIhr solltet ihre Sturmruferstäbe ohne größere Probleme finden, wenn man bedenkt, was für gigantische Blitze aus ihnen aufsteigen. Wollt ihr ein paar davon für mich umstürzen oder sie zerstören oder sowas? Ich würde auf jeden Fall besser schlafen.", sourceObjective = "Zerstört die Sturmruferstäbe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31757] = { id = 31757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Geister", description = "Die Shao-Tien haben die von ihnen gefangen gehaltenen gequälten Geister auf uns gehetzt. Schier endlos kommen sie die Goldene Treppe herab.\n\nTötet so viele dieser entfesselten Geister, wie Ihr könnt. Sie sind schwach, aber wenn Ihr nicht aufpasst, könnten sie Euch leicht überrennen.\n\nViel Glück.", sourceObjective = "Tötet 12 entfesselte Geister.", sourceObjectiveStatus = "unverified-source-field" }
quests[31758] = { id = 31758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laosige Arbeit", description = "Lao Samtfuß hat sich schon wieder oben auf der Goldenen Treppe gefangennehmen lassen. Ich will ihn nicht verteidigen, er ist einfach ein lausiger Schurke.\n\nAber wir sollten ihn vielleicht nicht einfach dort lassen. Könntet Ihr ihn bitte finden?", sourceObjective = "Rettet Lao Samtfuß.", sourceObjectiveStatus = "unverified-source-field" }
quests[31760] = { id = 31760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstschlag", description = "Die Mogu verleihen oben auf der Goldenen Treppe einer riesigen Steinmonstrosität Macht. Sie wollen sie ganz bestimmt gegen uns einsetzen.\n\nWas haltet Ihr davon, ihnen zu verdeutlichen, was wir von der Sache halten? Stellt sicher, dass sie es auch wirklich verstehen.", sourceObjective = "Verhindert, dass das Ungetüm der Shao-Tien an Macht gewinnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31761] = { id = 31761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demoralisierung", description = "Die Mogu haben oben auf der Treppe die Körper unserer Brüder aufgehäuft und führen ein garstiges Ritual durch, um ihnen ihre Geister zu entziehen und sie auf uns zu hetzen.\n\nFindet dieses Ritual und setzt ihm ein Ende. Die Mogu sollen sich noch lange daran erinnern können, was passieren wird, wenn sie es erneut versuchen.", sourceObjective = "Beendet das Geisterritual der Shao-Tien.", sourceObjectiveStatus = "unverified-source-field" }
quests[31762] = { id = 31762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bröckelndes Ungetüm", description = "Die Mogu haben es geschafft, eine riesige Steinstatue zu erwecken, in der Absicht, sie auf uns zu hetzen.\n\nAls Antwort darauf würde ich gern Euch auf sie hetzen.\n\nSie kommt von der Goldenen Treppe her auf uns zu. Zwingt sie in die Knie...", sourceObjective = "Zerstört das Ungetüm der Shao-Tien.", sourceObjectiveStatus = "unverified-source-field" }
quests[31765] = { id = 31765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot und tot!", description = "Sie haben unseren Antrieb kaputtgeschossen und wir sind hierher getrieben - HIERHER! Direkt in die Schusslinie des Feindes!\n\nIhr wisst, was zu tun ist, {name}. Geht unter Deck und bemannt die Geschütze!\n\nZeigt diesen Dreckskerlen, dass sie in UNSERER Schusslinie sind!", sourceObjective = "Benutzt ein Kanonenbootgeschütz, um 80 Gefolgsleute von Donnerwehr zu töten und 9 Kanonen von Donnerwehr zu zerstören.", progress = "Worauf wartet Ihr denn?! An die Geschütze!", completion = "Überlegene Feuerkraft der Horde vom Feinsten!\n\n...und Ihr habt Euch wohl auch recht gut geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31766] = { id = 31766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichere Landung", description = "Nazgrim befehligt den Bodenangriff und ersucht, dass Ihr unverzüglich losgeschickt werdet, um Euch mit ihm zu treffen.\n\nWir haben mehrere Kletterseile neben den Kanonen eingerichtet. Ihr werdet feststellen, dass Ihr damit am schnellsten nach unten gelangt, es sei denn, es endet böse.", sourceObjective = "Benutzt einen Abseilstrick, um nach unten zu gelangen.", completion = "Da seid Ihr ja!\n\nIch habe mir schon Sorgen gemacht, dass wir losstürmen und uns ohne Euch amüsieren müssen.", sourceObjectiveStatus = "unverified-source-field" }
